package diag.stirling;
import java.lang.reflect.*;
import java.util.*;

/** Uses real immutable AP facts, real RunSummaryStore and real ops.leaves; no analyzer starts. */
public class ProductionApiControl {
  static Object construct(String name,Object... args)throws Exception{
    Class<?> cls=Class.forName(name);
    outer:for(Constructor<?> c:cls.getDeclaredConstructors())if(c.getParameterCount()==args.length){
      Class<?>[] p=c.getParameterTypes();for(int i=0;i<p.length;i++)if(args[i]!=null&&!p[i].isPrimitive()&&!p[i].isInstance(args[i]))continue outer;
      c.setAccessible(true);return c.newInstance(args);
    }throw new NoSuchMethodException(name+" constructor/"+args.length);
  }
  static Object enumeration(String name,String value)throws Exception{return Enum.valueOf((Class)Class.forName(name),value);}
  public static class Config{public int getIndex(){return 6;}public int getFieldLimit(){return 5;}public String getDirection(){return "BACKWARD";}}
  public static class Result{public List<Object> actors;public String getStatus(){return "COMPLETE";}public List<Object>getAnalyzers(){return actors;}}
  public static class Actor{Object store;public Object getKey(){return "AdminSettingsController#updateSettingsSection(real-AP-control)";}public Object getSummaries(){return store;}public boolean getNonZeroInitial(){return false;}public long getSteps(){return 7;}public long getEdgeDeltas(){return 5;}public long getDemandLayerEdges(){return 3;}public long getRecordCrossings(){return 2;}public long getTriggerSeeds(){return 1;}public long getCfgDeliveryHits(){return 4;}public long getCfgDeliverySearches(){return 6;}}
  public static class Shared{Object ap,ops;public Object getAp(){return ap;}public Object getOps(){return ops;}}
  public static class Index{private List<Object> rows;}
  public static class Demand{private Map<Object,Object> byMethod;}
  public static class HandOff{Object demand;Map<Object,Integer> counts;public Object getDemand(){return demand;}public Object getDemandEdges(){return counts;}}
  public static void main(String[] args)throws Exception{
    Class.forName("org.opentaint.dataflow.bidi.driver.HandOff$Companion"); // Actual transformed bytecode verifies.
    String prefix="org.opentaint.dataflow.bidi.ap.";
    Class<?> decl=Class.forName(prefix+"MarkDeclarations");
    Object declarations=Proxy.newProxyInstance(decl.getClassLoader(),new Class<?>[]{decl},(p,m,a)->
        construct(prefix+"FullKey","control-group",a[0],null));
    Object marks=construct(prefix+"MarkTable",declarations);
    int mark=((Number)DemandCapture.callPrefix(marks,"full-","T")).intValue();
    Object slot=construct(prefix+"MarkSlot$Concrete",mark,null);
    Object cancellation=construct("org.opentaint.dataflow.util.Cancellation");DemandCapture.call(cancellation,"activate");
    Object ap=construct(prefix+"ApManager",cancellation,construct("org.opentaint.dataflow.util.RefManager"),marks);
    Object accessors=DemandCapture.call(ap,"getAccessors");
    Object field=construct("org.opentaint.dataflow.ap.ifds.FieldAccessor","control.Box","child","java.lang.Object");
    int accessor=((Number)DemandCapture.call(accessors,"index",field)).intValue();
    Object base=construct("org.opentaint.dataflow.ap.ifds.AccessPathBase$Argument",0,null);
    Object tail=enumeration(prefix+"Tail","ANY");
    Object exclusion=Class.forName(prefix+"ExclusionSet$Empty").getField("INSTANCE").get(null);
    Object fact=construct(prefix+"PathFact",base,List.of(accessor),tail,slot);
    Object pattern=construct(prefix+"Pattern",fact,exclusion);
    Object facts=DemandCapture.call(ap,"factsOf",fact,exclusion,enumeration(prefix+"Layer","DEMAND"));
    int secondMark=((Number)DemandCapture.callPrefix(marks,"full-","U")).intValue();
    Object secondSlot=construct(prefix+"MarkSlot$Concrete",secondMark,null);
    Object secondFact=construct(prefix+"PathFact",base,List.of(accessor),tail,secondSlot);
    Object secondPattern=construct(prefix+"Pattern",secondFact,exclusion);
    Object secondFacts=DemandCapture.call(ap,"factsOf",secondFact,exclusion,enumeration(prefix+"Layer","DEMAND"));
    Object store=construct("org.opentaint.dataflow.bidi.store.RunSummaryStore",ap,false);
    Object zero=DemandCapture.call(ap,"getZero");
    DemandCapture.call(store,"add",zero,facts);DemandCapture.call(store,"addDemand",zero,facts);
    DemandCapture.call(store,"add",zero,secondFacts);DemandCapture.call(store,"addDemand",zero,secondFacts);
    Actor actor=new Actor();actor.store=store;Result result=new Result();result.actors=List.of(actor);
    Shared shared=new Shared();shared.ap=ap;shared.ops=construct(prefix+"ApOps",ap);
    Index index=new Index();index.rows=List.of(construct(prefix+"DemandPattern",pattern,null),construct(prefix+"DemandPattern",secondPattern,null));
    Demand demand=new Demand();demand.byMethod=Map.of(actor.getKey(),index);
    HandOff handoff=new HandOff();handoff.demand=demand;handoff.counts=Map.of(actor.getKey(),2);
    Map<String,Object> output=DemandCapture.collect(handoff,new Config(),result,shared);
    if(!output.get("normalizedOutgoingRows").equals(2L))throw new AssertionError(output);
    String encoded=DemandCapture.json(output);
    if(!encoded.contains("Box#child")||!encoded.contains("markName\":\"T")||!encoded.contains("markName\":\"U")||!encoded.contains("premise=ZERO|layer=DEMAND|recordEligible=false"))throw new AssertionError(encoded);
    Map<?,?> own=(Map<?,?>)((Map<?,?>)output.get("owners")).values().iterator().next();
    for(String scope:List.of("normalizedOutgoing","selectedPublications","rawSummaries")){
      Map<?,?> stat=(Map<?,?>)own.get(scope);Map<?,?> geometry=(Map<?,?>)stat.get("locationGeometry");
      if(!geometry.get("count").equals(1)||!geometry.get("countStatus").equals("EXACT")||!stat.get("leafMemberships").equals(2L))throw new AssertionError(encoded);
    }
    DemandCapture.GeometryPool pool=new DemandCapture.GeometryPool(1);
    if(pool.intern("first")!=0||pool.intern("first")!=0||pool.intern("second")!=-1||pool.rejected!=1)throw new AssertionError("Scratch cap control");
    System.out.println("PASS actual transformed HandOff bytecode; full T/U mark names; 2 memberships/1 geometry in 3 separate stores; real AP leaves/stores; explicit scratch cap");
  }
}

