package diag.stirling;

import java.lang.instrument.*;
import java.security.ProtectionDomain;
import org.objectweb.asm.*;

/** Injects a read-only barrier callback; no propagation or key class is transformed. */
public final class DemandAgent {
  static final String TARGET = "org/opentaint/dataflow/bidi/driver/HandOff$Companion";
  static final String DESC = "(Lorg/opentaint/dataflow/bidi/engine/RunConfig;Lorg/opentaint/dataflow/bidi/engine/RunResult;Lorg/opentaint/dataflow/bidi/driver/ReportBuilder;Lorg/opentaint/dataflow/bidi/engine/SharedObjects;)Lorg/opentaint/dataflow/bidi/driver/HandOff;";
  public static void premain(String args, Instrumentation inst) {
    DemandCapture.configure(args);
    inst.addTransformer(new ClassFileTransformer() {
      @Override public byte[] transform(ClassLoader loader, String name, Class<?> redef,
          ProtectionDomain domain, byte[] bytes) {
        if (!TARGET.equals(name)) return null;
        byte[] output = transformBytes(bytes);
        DemandCapture.notice("TRANSFORMED " + name);
        return output;
      }
    });
  }
  public static byte[] transformBytes(byte[] bytes) {
    ClassReader reader = new ClassReader(bytes);
    ClassWriter writer = new ClassWriter(reader, ClassWriter.COMPUTE_MAXS);
    final int[] matched = {0};
    reader.accept(new ClassVisitor(Opcodes.ASM9, writer) {
      @Override public MethodVisitor visitMethod(int access, String name, String desc,
          String signature, String[] exceptions) {
        MethodVisitor target = super.visitMethod(access, name, desc, signature, exceptions);
        if (!name.equals("of") || !desc.equals(DESC)) return target;
        matched[0]++;
        return new MethodVisitor(Opcodes.ASM9, target) {
          @Override public void visitInsn(int opcode) {
            if (opcode == Opcodes.ARETURN) {
              super.visitInsn(Opcodes.DUP);
              super.visitVarInsn(Opcodes.ALOAD, 1); // RunConfig
              super.visitVarInsn(Opcodes.ALOAD, 2); // frozen RunResult
              super.visitVarInsn(Opcodes.ALOAD, 4); // SharedObjects
              super.visitMethodInsn(Opcodes.INVOKESTATIC, "diag/stirling/DemandCapture", "capture",
                  "(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V", false);
            }
            super.visitInsn(opcode);
          }
        };
      }
    }, 0);
    if (matched[0] != 1) throw new IllegalStateException("Expected one immutable HandOff.of hook, got " + matched[0]);
    return writer.toByteArray();
  }
}

