package diag.stirling;

import java.io.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/** Reflection avoids loading analyzer classes during premain. All references are callback-local. */
public final class DemandCapture {
  static Path directory;
  static final Map<String, Method> methods = new ConcurrentHashMap<>();
  static final int EXAMPLES = 24;
  public static void configure(String args) {
    if (args == null || args.isBlank()) throw new IllegalArgumentException("Agent argument must name an external output directory");
    directory = Path.of(args);
    try { Files.createDirectories(directory); } catch (IOException e) { throw new UncheckedIOException(e); }
    notice("ARMED minRun=4 readOnlyBarrier=true");
  }
  static void notice(String value) {
    System.err.println("STIRLING_DEMAND_PROBE " + value);
  }
  public static void capture(Object handOff, Object config, Object result, Object shared) {
    long start = System.nanoTime();
    try {
      int run = ((Number) call(config, "getIndex")).intValue();
      if (run < 4) return;
      if (!"COMPLETE".equals(call(result, "getStatus").toString())) throw new IllegalStateException("Expected completed owners");
      Map<String,Object> output = collect(handOff, config, result, shared);
      output.put("captureNanosBeforeWrite", System.nanoTime() - start);
      Path destination = directory.resolve("run-" + run + "-demand.json");
      Path temporary = directory.resolve("run-" + run + "-demand.tmp");
      Files.writeString(temporary, json(output) + "\n", StandardOpenOption.CREATE_NEW);
      Files.move(temporary, destination, StandardCopyOption.ATOMIC_MOVE);
      notice("COMPLETE run=" + run + " path=" + destination + " nanos=" + (System.nanoTime()-start));
    } catch (Throwable error) {
      // Diagnostics never replace the original result or affect analyzer completion.
      notice("FAILED " + error);
      error.printStackTrace(System.err);
      try {
        if (directory != null) Files.writeString(directory.resolve("capture-failure.txt"),
            Instant.now() + " " + error + "\n", StandardOpenOption.CREATE, StandardOpenOption.APPEND);
      } catch (Throwable ignored) { }
    }
  }
  static Map<String,Object> collect(Object handOff, Object config, Object result, Object shared) throws Exception {
    String direction = call(config,"getDirection").toString();
    Object ops = call(shared,"getOps");
    Object ap = call(shared,"getAp");
    Object accessors = call(ap,"getAccessors");
    Object marks = call(ap,"getMarks");
    Map<String,Object> output = map("schema","stirling-passive-barrier-v1", "diagnosticOnly",true,
        "utc",Instant.now().toString(), "run",call(config,"getIndex"), "direction",direction,
        "fieldLimit",call(config,"getFieldLimit"), "status",call(result,"getStatus").toString(),
        "scope","Normalized outgoing rows; selected publication leaves; raw summary leaves. Distinct counters.");
    Map<Object,Object> outgoing = (Map<Object,Object>) field(call(handOff,"getDemand"),"byMethod");
    Map<Object,Object> counts = (Map<Object,Object>) call(handOff,"getDemandEdges");
    Map<String,Object> owners = new TreeMap<>();
    Map<String,Object> actorStatistics = new TreeMap<>();
    GeometryPool geometryPool = new GeometryPool(250000);
    Map<Integer,String> markNames = new HashMap<>();
    long normalizedTotal = 0;
    for (Object actor : (List<?>) call(result,"getAnalyzers")) {
      Object key = call(actor,"getKey");
      String name = key.toString();
      actorStatistics.put(name,map("steps",call(actor,"getSteps"),"edgeDeltas",call(actor,"getEdgeDeltas"),
          "demandLayerEdges",call(actor,"getDemandLayerEdges"),"recordCrossings",call(actor,"getRecordCrossings"),
          "triggerSeeds",call(actor,"getTriggerSeeds"),"nonZeroInitial",call(actor,"getNonZeroInitial"),
          "cfgDeliveryHits",call(actor,"getCfgDeliveryHits"),"cfgDeliverySearches",call(actor,"getCfgDeliverySearches"),
          "initialCount",null,"initialCountStatus","released before HandOff barrier"));
      boolean focus = name.contains("AdminSettingsController#updateSettingsSection(") ||
          name.contains("PipelineProcessor#runPipelineAgainstFiles(") || name.contains("GetInfoOnPDF#getPdfInfo(");
      Stat normalized = new Stat(focus,geometryPool,markNames), selected = new Stat(focus,geometryPool,markNames), raw = new Stat(focus,geometryPool,markNames);
      Object indexed = outgoing.get(key);
      if (indexed != null) for (Object demand : (List<?>) field(indexed,"rows")) {
        Object entry = call(demand,"getEntry"), exit = call(demand,"getExit");
        normalized.add(entry, exit == null ? "UNPAIRED" : "PAIRED", accessors, marks, exit == null ? "null" : geometry(exit));
        if (exit != null) normalized.count("exitHeader", header(exit));
      }
      normalizedTotal += normalized.leaves;
      long expected = ((Number) counts.getOrDefault(key, 0)).longValue();
      if (expected != normalized.leaves) throw new IllegalStateException("Outgoing mismatch " + name + ": " + expected + " != " + normalized.leaves);
      Object summaries = call(actor,"getSummaries");
      summaries(summaries,"demandEdges",selected,ops,accessors,marks,direction);
      summaries(summaries,"all",raw,ops,accessors,marks,direction);
      if (normalized.leaves + selected.leaves + raw.leaves == 0) continue;
      owners.put(name, map("normalizedOutgoing",normalized.finish(accessors), "selectedPublications",selected.finish(accessors),
          "rawSummaries",raw.finish(accessors), "nonZeroInitial",call(actor,"getNonZeroInitial")));
    }
    output.put("normalizedOutgoingRows", normalizedTotal);
    output.put("normalizedOutgoingMethodKeys", counts.size());
    output.put("owners", owners);
    output.put("actorStatistics",actorStatistics);
    output.put("geometryScratch",map("maxSharedKeys",geometryPool.limit,"retainedKeysDuringCapture",geometryPool.ids.size(),
        "rejectedNewKeys",geometryPool.rejected,"scope","Shared scratch strings for focused owners; per-store BitSets remain separate; all released after callback"));
    output.put("limits", List.of("This is a separate diagnostic replay, not a timing replacement for the clean campaign.",
        "Examples are bounded; histograms and normalized outgoing row counts are complete for this callback.",
        "Accessor occurrence counts count every position; row-presence counts each accessor at most once per row.",
        "Raw eligibility counts apply the existing R1 routing header predicate after normal runtime validation; they do not re-run record validation.",
        "Focused location geometry excludes mark on both endpoints. A shared 250000-key scratch cap is explicit; a capped store reports a lower bound.",
        "The collector invokes leaves only after complete owners freeze; traversal can add allocation and consume later-run budget."));
