          call(call(premise,"member",0),"getMark").getClass().getSimpleName();
      String layer=call(facts,"getLayer").toString();
      boolean eligible="NORMAL".equals(layer) && size == 1 && !(direction.equals("BACKWARD") && zero);
      String lane="premise="+kind+"|layer="+layer+"|recordEligible="+eligible;
      String premiseGeometry="null";
      if(stat.focus && !zero) {
        List<String> members=new ArrayList<>();
        for(int i=0;i<size;i++)members.add(geometry(call(call(premise,"member",i),"toPattern")));
        Collections.sort(members);premiseGeometry=members.size()==1?members.get(0):members.toString();
      }
      stat.groups++;
      stat.count("groupsByLane", lane);
      Iterator<?> leaves=iterator(call(ops,"leaves",facts));
      while(leaves.hasNext()) stat.add(leaves.next(), lane, accessors, marks, premiseGeometry);
    }
  }
  static final class Stat {
    final boolean focus;
    final GeometryPool geometryPool;
    final Map<Integer,String> markNames;
    final BitSet geometries=new BitSet();
    boolean geometryCapped;
    long leaves,groups;
    final Map<String,Map<String,Long>> hist=new TreeMap<>();
    final Map<Integer,Long> occurrences=new TreeMap<>(), presence=new TreeMap<>();
    final LinkedHashMap<String,Object> examples=new LinkedHashMap<>();
    final Map<Integer,Object> depthExamples=new TreeMap<>();
    Stat(boolean focus,GeometryPool geometryPool,Map<Integer,String> markNames){this.focus=focus;this.geometryPool=geometryPool;this.markNames=markNames;}
    void count(String bucket,String value){hist.computeIfAbsent(bucket,k->new TreeMap<>()).merge(value,1L,Long::sum);}
    void add(Object pattern,String lane,Object accessors,Object marks,String exitGeometry) throws Exception {
      Object fact=call(pattern,"getFact"), mark=call(fact,"getMark");
      List<?> path=(List<?>)call(fact,"getPath");
      String base=call(fact,"getBase").getClass().getSimpleName();
      String exactBase=call(fact,"getBase").toString();
      String tail=call(fact,"getTail").toString();
      String markKind=mark.getClass().getSimpleName();
      leaves++;
      count("leavesByLane",lane);
      count("headers",lane+"|base="+base+"|tail="+tail+"|mark="+markKind+"|depth="+path.size());
      count("tail",tail); count("markKind",markKind); count("pathLength",Integer.toString(path.size()));
      count("baseKind",base); count("exclusionKind",call(pattern,"getExclusion").getClass().getSimpleName());
      count("mark", mark.toString());
      count("markName",decodeMark(mark,marks,markNames));
      count("base",exactBase);count("baseAndDepth",exactBase+"|"+path.size());
      if(!path.isEmpty()) {count("firstAccessorId",path.get(0).toString());count("baseAndFirstAccessorId",exactBase+"|"+path.get(0));}
      if(focus){int id=geometryPool.intern(geometry(pattern)+"=>"+exitGeometry);if(id<0)geometryCapped=true;else geometries.set(id);}
      Set<Integer> unique=new HashSet<>();
      for(Object id:path){int n=((Number)id).intValue();occurrences.merge(n,1L,Long::sum); unique.add(n);}
      count("uniqueAccessorsPerPath",Integer.toString(unique.size()));
      for(int i=1;i<path.size();i++)count("adjacentAccessorIds",path.get(i-1)+">"+path.get(i));
      for(int id:unique)presence.merge(id,1L,Long::sum);
      if(focus && (examples.size()<EXAMPLES || !depthExamples.containsKey(path.size()))) {
        Object decoded=describe(pattern,accessors,marks);
        String signature=lane+"|"+decoded;
        if(examples.size()<EXAMPLES)examples.putIfAbsent(signature,map("lane",lane,"pattern",decoded));
        depthExamples.putIfAbsent(path.size(),map("lane",lane,"pattern",decoded));
      }
    }
    Map<String,Object> finish(Object accessors) throws Exception {
      return map("leafMemberships",leaves,"groups",groups,"histograms",hist,
          "accessorOccurrences",decodeCounts(occurrences,accessors),"accessorRowPresence",decodeCounts(presence,accessors),
          "boundedExamples",new ArrayList<>(examples.values()),"oneExamplePerPathLength",depthExamples,
          "locationGeometry",map("count",focus?geometries.cardinality():null,"countStatus",!focus?"not requested":geometryCapped?"LOWER_BOUND_CAPPED":"EXACT",
              "excludes","mark on both endpoints; retains base,path,tail,E and exit/premise geometry","scratchCap",geometryPool.limit));
    }
  }
  static final class GeometryPool {
    final int limit;long rejected;final Map<String,Integer> ids=new HashMap<>();
    GeometryPool(int limit){this.limit=limit;}
    int intern(String key){Integer old=ids.get(key);if(old!=null)return old;if(ids.size()>=limit){rejected++;return -1;}int id=ids.size();ids.put(key,id);return id;}
  }
  static String geometry(Object pattern) throws Exception {
    Object f=call(pattern,"getFact");
    return call(f,"getBase")+"|"+call(f,"getPath")+"|"+call(f,"getTail")+"|"+call(pattern,"getExclusion");
  }
  static String decodeMark(Object mark,Object marks,Map<Integer,String> names)throws Exception {
    if(!mark.getClass().getSimpleName().equals("Concrete"))return mark.toString();
    int id=((Number)callPrefix(mark,"getMark-")).intValue();String name=names.get(id);
    if(name==null){name=callPrefix(marks,"name-",id).toString();names.put(id,name);}return id+":"+name;
  }
  static Map<String,Long> decodeCounts(Map<Integer,Long> source,Object accessors) throws Exception {
    Map<String,Long> out=new TreeMap<>();
    for(var e:source.entrySet())out.put(e.getKey()+":"+accessorName(call(accessors,"accessor",e.getKey())),e.getValue());
    return out;
  }
  static String header(Object pattern) throws Exception {
    Object f=call(pattern,"getFact");
    return "base="+call(f,"getBase")+"|tail="+call(f,"getTail")+"|mark="+call(f,"getMark")+"|depth="+((List<?>)call(f,"getPath")).size();
  }
  static Object describe(Object pattern,Object accessors,Object marks) throws Exception {
    Object f=call(pattern,"getFact"), mark=call(f,"getMark");
    List<String> path=new ArrayList<>();
    for(Object id:(List<?>)call(f,"getPath"))path.add(accessorName(call(accessors,"accessor",((Number)id).intValue())));
    Object name=null;
    if(mark.getClass().getSimpleName().equals("Concrete")) {
      int id=((Number)callPrefix(mark,"getMark-")).intValue();
      name=callPrefix(marks,"name-",id);
    }
    return map("base",call(f,"getBase").toString(),"path",path,"tail",call(f,"getTail").toString(),
        "mark",mark.toString(),"markName",name,"exclusion",call(pattern,"getExclusion").toString());
  }
  static String accessorName(Object accessor) throws Exception {
    if(accessor.getClass().getSimpleName().equals("FieldAccessor"))return call(accessor,"getClassName")+"#"+call(accessor,"getFieldName")+"#"+call(accessor,"getFieldType");
    return accessor.toString();
  }
  static Object callPrefix(Object object,String prefix,Object... args) throws Exception {
    String key=object.getClass().getName()+"#PREFIX"+prefix+"/"+args.length;
    Method cached=methods.get(key);if(cached!=null)return cached.invoke(object,args);
    for(Method m:object.getClass().getMethods())if(m.getName().startsWith(prefix)&&m.getParameterCount()==args.length){m.setAccessible(true);methods.put(key,m);return m.invoke(object,args);}
    throw new NoSuchMethodException(object.getClass()+" "+prefix);
  }
  static Object call(Object object,String name,Object... args) throws Exception {
    String key=object.getClass().getName()+"#"+name+"/"+args.length;
    Method method=methods.get(key);
    if(method==null){
      outer:for(Method m:object.getClass().getMethods())if(m.getName().equals(name)&&m.getParameterCount()==args.length){
        Class<?>[] p=m.getParameterTypes();
        for(int i=0;i<p.length;i++)if(args[i]!=null&&!p[i].isPrimitive()&&!p[i].isInstance(args[i]))continue outer;
        m.setAccessible(true);method=m;methods.put(key,m);break;
      }
      if(method==null)throw new NoSuchMethodException(key);
    }
    return method.invoke(object,args);
  }
  static Iterator<?> iterator(Object sequence) throws Exception {return (Iterator<?>)call(sequence,"iterator");}
  static Object field(Object object,String name) throws Exception {Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
  static Map<String,Object> map(Object... cells){Map<String,Object> out=new LinkedHashMap<>();for(int i=0;i<cells.length;i+=2)out.put(cells[i].toString(),cells[i+1]);return out;}
  static String json(Object value){
    if(value==null)return "null";if(value instanceof Number||value instanceof Boolean)return value.toString();
    if(value instanceof Map<?,?>){StringJoiner j=new StringJoiner(",","{","}");for(var e:((Map<?,?>)value).entrySet())j.add(json(e.getKey().toString())+":"+json(e.getValue()));return j.toString();}
    if(value instanceof Iterable<?>){StringJoiner j=new StringJoiner(",","[","]");for(Object x:(Iterable<?>)value)j.add(json(x));return j.toString();}
    StringBuilder out=new StringBuilder("\"");for(char c:value.toString().toCharArray()){switch(c){case '"':out.append("\\\"");break;case '\\':out.append("\\\\");break;case '\n':out.append("\\n");break;case '\r':out.append("\\r");break;case '\t':out.append("\\t");break;default:if(c<32)out.append(String.format("\\u%04x",(int)c));else out.append(c);}}return out.append('"').toString();
  }
}

alias-control/AliasCopyControl.java.content:
import java.util.*;
import it.unimi.dsi.fastutil.ints.IntOpenHashSet;
import org.opentaint.dataflow.ap.ifds.analysis.alias.*;
import org.opentaint.dataflow.jvm.ap.ifds.JIRLocalAliasAnalysis.AliasAccessor;
import org.opentaint.dataflow.jvm.ap.ifds.alias.*;
import org.opentaint.dataflow.configuration.jvm.*;

/** Current DSU/heap and CopyAllMarks APIs. The small position adapter mirrors the private production adapter. */
public final class AliasCopyControl {
  static final class Case {
    final AAInfoManager manager=new AAInfoManager();
    State state=State.Companion.empty(manager,new DsuMergeStrategy(manager));
    final AAInfo x=new LocalAlias.SimpleLoc(new RefValue.Arg(0));
    final AAInfo result=new LocalAlias.SimpleLoc(new RefValue.Arg(1));
    final Map<String,FieldAlias> fields=new LinkedHashMap<>();
    Case(){manager.getOrAdd(x);manager.getOrAdd(result);}
    int id(AAInfo i){return manager.getOrAdd(i);}
    int repr(AAInfo i){return state.aliasGroupId(id(i));}
    AAInfo child(AAInfo base,FieldAlias f){return new HeapAlias(repr(base),f);}
    FieldAlias field(String owner,String name){return fields.computeIfAbsent(owner+"#"+name,k->new FieldAlias(new AliasAccessor.Field(owner,name,"java.lang.Object"),false));}
    AAInfo position(Position p){
      if(p instanceof This)return x;
      if(p instanceof Result)return result;
      if(p instanceof PositionWithAccess){PositionWithAccess q=(PositionWithAccess)p;PositionAccessor.FieldAccessor f=(PositionAccessor.FieldAccessor)q.getAccess();return child(position(q.getBase()),field(f.getClassName(),f.getFieldName()));}
      throw new AssertionError(p);
    }
    void apply(CopyAllMarks action){
      // Corresponds to JIRLocalAliasAnalysis75–86 and DSUAliasAnalysis183–196.
      AAInfo from=position(action.getFrom()),to=position(action.getTo());
      state=state.mergeAliasSets(new IntOpenHashSet(new int[]{id(from),id(to)}));
    }
    boolean same(AAInfo a,AAInfo b){return repr(a)==repr(b);}
    boolean everyWordAliases(AAInfo at,List<FieldAlias> alphabet,int length){
      if(length==0)return same(at,x);
      for(FieldAlias f:alphabet)if(!everyWordAliases(child(at,f),alphabet,length-1))return false;
      return true;
    }
  }
  static CopyAllMarks rootCopy(){return new CopyAllMarks(This.INSTANCE,Result.INSTANCE);}
  static CopyAllMarks fieldCopy(String owner,String field){return new CopyAllMarks(new PositionWithAccess(This.INSTANCE,new PositionAccessor.FieldAccessor(owner,field,"java.lang.Object")),Result.INSTANCE);}
  static void require(boolean condition,String text){if(!condition)throw new AssertionError(text);}
  public static void main(String[] args)throws Exception{
    Case entry=new Case();entry.apply(rootCopy());entry.apply(fieldCopy("java.util.Map$Entry","Value"));
    FieldAlias value=entry.field("java.util.Map$Entry","Value");
    require(entry.same(entry.x,entry.child(entry.x,value)),"Entry broad+Value copies must form x=x.Value in current DSU");
    require(entry.everyWordAliases(entry.x,List.of(value),8),"Entry Value^8 self cycle");
    Case precise=new Case();precise.apply(fieldCopy("java.util.Map$Entry","Value"));
    require(!precise.same(precise.x,precise.child(precise.x,precise.field("java.util.Map$Entry","Value"))),"Precise-only control must not merge receiver with Value");
    Case iterator=new Case();iterator.apply(rootCopy());iterator.apply(fieldCopy("org.apache.commons.lang3.text.StrTokenizer","<rule-storage>"));
    FieldAlias storage=iterator.field("org.apache.commons.lang3.text.StrTokenizer","<rule-storage>");
    require(iterator.same(iterator.x,iterator.child(iterator.x,storage)),"StrTokenizer root+storage self cycle");
    Case branching=new Case();branching.apply(rootCopy());
    branching.apply(fieldCopy("java.util.Iterator","Element"));
    branching.apply(fieldCopy("org.apache.commons.lang3.text.StrTokenizer","<rule-storage>"));
    branching.apply(fieldCopy("org.apache.http.HeaderIterator","<rule-storage>"));
    List<FieldAlias> alphabet=new ArrayList<>(branching.fields.values());require(alphabet.size()==3,"Three independent field labels");
    long sum=0,power=1;
    for(int depth=0;depth<=6;depth++){
      require(branching.everyWordAliases(branching.x,alphabet,depth),"All labelled words must return to x at depth "+depth);
      sum+=power;System.out.println("DSU_PATH_WITNESS limit="+depth+" exactDepthPaths="+power+" pathsAtMostLimit="+sum+" allAliasReceiver=true");power*=3;
    }
    Class<?> raw=Class.forName("org.opentaint.dataflow.configuration.jvm.serialized.SerializedRule$PassThrough");
    require(Arrays.stream(raw.getDeclaredMethods()).anyMatch(m->m.getName().equals("getTaintCopyOnly")),"Raw parsed flag must exist");
    require(Arrays.stream(TaintPassThrough.class.getDeclaredMethods()).noneMatch(m->m.getName().equals("getTaintCopyOnly")),"Current bound rule has no taintCopyOnly accessor");
    System.out.println("PASS actual production DSU root+field self cycles; precise-only control; 3^L labelled paths; raw flag/bound API shape");
    System.out.println("LIMIT: position-to-AA adapter is a small source-corresponding control, not the private production provider; no project aliases or analyzer iteration were executed");
  }
}

constant-control/ConstantStageControl.ja.content:
import java.lang.reflect.*;
import java.util.*;
import kotlin.Unit;
import kotlin.jvm.functions.Function2;
import org.opentaint.dataflow.ap.ifds.AccessPathBase;
import org.opentaint.dataflow.bidi.ap.*;
import org.opentaint.dataflow.bidi.interp.*;
import org.opentaint.ir.api.common.cfg.CommonInst;

/** Narrow control: real FormApplier dispatch and real binding reversal; no full suffix or report proof. */
public final class ConstantStageControl {
  static PathFact star(AccessPathBase b){return new PathFact(b,List.of(),Tail.STAR,MarkSlot.Companion.getSTAR());}
  static PathEdge copy(AccessPathBase from,AccessPathBase to){return new PathEdge(star(from),star(to),ExclusionSet.Empty.INSTANCE,ExclusionSet.Empty.INSTANCE,ExclusionSet.Empty.INSTANCE);}
  static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
  public static void main(String[] args){
    AccessPathBase constant=new AccessPathBase.Constant("java.lang.String","\"literal\"");
    AccessPathBase arg=AccessPathBase.Companion.Argument(0), local=AccessPathBase.Companion.LocalVar(1);
    CommonInst node=(CommonInst)Proxy.newProxyInstance(CommonInst.class.getClassLoader(),new Class<?>[]{CommonInst.class},(p,m,a)->{
      if(m.getName().equals("toString"))return "constant-stage-control";
      if(m.getName().equals("hashCode"))return System.identityHashCode(p);
      if(m.getName().equals("equals"))return p==a[0];
      throw new AssertionError("Unused CommonInst method "+m);
    });
    FactAlgebra<String,AccessPathBase> algebra=(FactAlgebra<String,AccessPathBase>)Proxy.newProxyInstance(FactAlgebra.class.getClassLoader(),new Class<?>[]{FactAlgebra.class},(p,m,a)->{
      switch(m.getName()){
        case "base":return a[0];
        case "reached":case "filtered":return Unit.INSTANCE;
        case "filter":return a[0];
        case "applyEdgeAt": ((Function2<String,AccessPathBase,Unit>)a[4]).invoke((String)a[2],((MicroEdge)a[0]).getEdge().getTo().getBase());return Unit.INSTANCE;
        case "operationResult":((Function2<String,AccessPathBase,Unit>)a[5]).invoke((String)a[1],(AccessPathBase)a[3]);return Unit.INSTANCE;
        default:throw new AssertionError("Unexpected algebra call "+m);
      }
    });
    FormApplier<String,AccessPathBase> apply=new FormApplier<>(algebra);
    Place place=new Place(node,false,false,null,List.of(),null,null,false,null,null);
    MicroEdgeBuilder backBuilder=new MicroEdgeBuilder();backBuilder.edge(copy(arg,local));
    StatementSummary bindBack=backBuilder.buildStage();
    List<AccessPathBase> outputs=new ArrayList<>();
    apply.statement(bindBack,"I",constant,place,(pr,f)->{outputs.add(f);return Unit.INSTANCE;},(pr,f)->{outputs.add(f);return Unit.INSTANCE;});
    check(outputs.equals(List.of(constant)),"Statement mode must preserve an untouched Constant");
    outputs.clear();apply.stage(bindBack,"I",constant,place,(pr,f,e)->{outputs.add(f);return Unit.INSTANCE;});
    check(outputs.isEmpty(),"Stage mode must drop Constant with no matching binding source");
    outputs.clear();apply.stage(bindBack,"I",arg,place,(pr,f,e)->{outputs.add(f);return Unit.INSTANCE;});
    check(outputs.equals(List.of(local)),"Forward binding positive control");
    MicroEdgeBuilder inBuilder=new MicroEdgeBuilder();inBuilder.edge(copy(constant,arg));
    StatementSummary reversedIn=inBuilder.buildStage().reversed();
    outputs.clear();apply.stage(reversedIn,"I",constant,place,(pr,f,e)->{outputs.add(f);return Unit.INSTANCE;});
    check(outputs.isEmpty(),"Reversed BIND_IN must not synthesize a Constant identity");
    outputs.clear();apply.stage(reversedIn,"I",arg,place,(pr,f,e)->{outputs.add(f);return Unit.INSTANCE;});
    check(outputs.equals(List.of(constant)),"A nonconstant callee requirement can create a local literal requirement at reversed actual binding");
    System.out.println("PASS real FormApplier: untouched statement keeps Constant; strict call stage drops it; reversed binding adds no Constant identity; formal->literal local route remains");
    System.out.println("LIMIT: edge algebra is a base-copy adapter. This is not full AP, suffix callback, source-hit, native-record or stopping equivalence.");
  }
}

observer-controls/agent/AgentBytecodeCon.content:
import java.util.*;
import java.io.*;
import org.objectweb.asm.*;
import org.objectweb.asm.util.CheckClassAdapter;
/** Independent structural verifier: production calls/fields/allocations/constants remain byte-for-byte symbolic sequences. */
public class AgentBytecodeControl {
 static List<String> effects(byte[] bytes){var out=new ArrayList<String>();new ClassReader(bytes).accept(new ClassVisitor(Opcodes.ASM9){public MethodVisitor visitMethod(int a,String n,String d,String s,String[] e){out.add("METHOD "+n+d);return new MethodVisitor(Opcodes.ASM9){public void visitMethodInsn(int o,String w,String n,String d,boolean i){if(!w.equals("DeliveryProbe"))out.add("CALL "+o+" "+w+"."+n+d+" "+i);}public void visitFieldInsn(int o,String w,String n,String d){out.add("FIELD "+o+" "+w+"."+n+d);}public void visitTypeInsn(int o,String t){out.add("TYPE "+o+" "+t);}public void visitLdcInsn(Object v){out.add("CONST "+v);}public void visitInvokeDynamicInsn(String n,String d,Handle h,Object... b){out.add("INDY "+n+d+h+Arrays.toString(b));}};}},0);return out;}
 public static void main(String[] a)throws Exception{
  int classes=0;
  for(String name:DeliveryProbeAgent.TARGETS){byte[] before=AgentBytecodeControl.class.getClassLoader().getResourceAsStream(name+".class").readAllBytes();byte[] after=DeliveryProbeAgent.instrument(name,before);
   if(!effects(before).equals(effects(after)))throw new AssertionError("Changed production effects: "+name);
   StringWriter errors=new StringWriter();CheckClassAdapter.verify(new ClassReader(after),AgentBytecodeControl.class.getClassLoader(),false,new PrintWriter(errors));if(!errors.toString().isBlank())throw new AssertionError(name+" "+errors);
   classes++;System.out.println("PASS "+name+" original="+DeliveryProbeAgent.sha(before)+" transformed="+DeliveryProbeAgent.sha(after));
  }
  System.out.println("PASS "+classes+" transformed classes: ASM verifier and unchanged production method/field/allocation/constant sequences");
 }
}

observer-controls/agent/AgentMaskControl.content:
import org.opentaint.dataflow.ap.ifds.AccessPathBase;
import org.opentaint.dataflow.bidi.ap.*;
/** Structural equality control independent of observed campaign counts. */
public class AgentMaskControl {
 public static void main(String[] a){
  var leaf=new TaintLeaves(new MarkSet(new int[]{1}),MarkSet.Companion.getEMPTY());
  var root=new TrieNode<TaintLeaves>(leaf,null,null,false);
  var plain=new TaintTree(AccessPathBase.Return.INSTANCE,Layer.NORMAL,root,ExclusionSet.Empty.INSTANCE,Tail.ANY_TAINT,null);
  var protectedFact=new TaintTree(AccessPathBase.Return.INSTANCE,Layer.NORMAL,root,ExclusionSet.Empty.INSTANCE,Tail.ANY_TAINT,root);
  if(!plain.equals(protectedFact))throw new AssertionError("ordinary Facts equality contract");
  if(new DeliveryProbe.FullFacts(plain).equals(new DeliveryProbe.FullFacts(protectedFact)))throw new AssertionError("sampler lost protection");
  var demand=new TaintTree(AccessPathBase.Return.INSTANCE,Layer.DEMAND,root,ExclusionSet.Empty.INSTANCE,Tail.ANY_TAINT,null);
  if(new DeliveryProbe.FullFacts(plain).equals(new DeliveryProbe.FullFacts(demand)))throw new AssertionError("sampler lost layer");
  if(!new DeliveryProbe.FullFacts(plain).equals(new DeliveryProbe.FullFacts(plain)))throw new AssertionError("same complete fact unequal");
  System.out.println("PASS complete Facts equality preserves protection and layer");
 }
}

observer-controls/agent/AgentSemanticCon.content:
import java.util.*;
import java.lang.reflect.*;
import org.opentaint.dataflow.ap.ifds.AccessPathBase;
import org.opentaint.dataflow.bidi.ap.*;
import org.opentaint.dataflow.bidi.engine.*;
import org.opentaint.dataflow.bidi.driver.*;
import org.opentaint.dataflow.bidi.fixtures.MethodAnalysisFixtures;
import org.opentaint.dataflow.bidi.interp.*;
import org.opentaint.dataflow.bidi.store.*;
/** Same finite run with and without -javaagent must emit identical semantic rows. */
public class AgentSemanticControl {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] argv)throws Exception{
  try(MethodAnalysisFixtures f=new MethodAnalysisFixtures()){
   var ex=ExclusionSet.Empty.INSTANCE;var star=MarkSlot.Companion.getSTAR();var ret=AccessPathBase.Return.INSTANCE;
   var config=new RunConfig(4,3,new DemandStore.Builder(f.getManager()).build(),f.getRecords(),new SeedIndex(Map.of()),List.of(f.getKey()),false,MarkMode.FULL,FieldLimitSchedule.REPEAT_RUN1);
   var call=f.inst(1);var caller=f.getStore().key("wrapper",0);
   var plan=new CallPlan(Set.of(ret),List.of(new CallStage.Callees(CallPoint.BEFORE,CallPoint.AFTER,List.of(f.getKey()))),List.of(),CallPoint.BEFORE,CallPoint.AFTER,Set.of(),true);
   f.call(1,plan,f.getCallExpression());
   RunMethodAnalyzer core=f.core(config,null,RunMethodCallServices::new,caller,false);
   var storage=new SummaryStorage(f.getKey(),f.getManager(),f.getOps(),ProtocolSteps.Inline.INSTANCE,null,false);
   SubscriptionPort port=(SubscriptionPort)Proxy.newProxyInstance(AgentSemanticControl.class.getClassLoader(),new Class[]{SubscriptionPort.class},(p,m,a)->switch(m.getName()){
    case "getConfig"->config;case "getOps"->f.getOps();case "getSteps"->ProtocolSteps.Inline.INSTANCE;case "getStatistics","getAbstractionStatistics","getRequestBatchStatistics","getStaticService"->null;
    case "summaryStorage"->storage;case "applier"->core;case "post","send"->true;default->throw new UnsupportedOperationException(m.getName());});
   var sm=new SubscriptionManager(port);
   var initial=f.getManager().initial(f.pattern(ret,List.of(),Tail.STAR,star,ex));
   var g=f.fact(AccessPathBase.This.INSTANCE,List.of(f.field("tasks")),Tail.STAR,star,ex,Layer.NORMAL);
   var actual=f.fact(ret,List.of(),Tail.STAR,star,ex,Layer.NORMAL);
   var p1=f.getManager().initial(f.pattern(ret,List.of(f.field("a")),Tail.STAR,star,ex));
   var p2=f.getManager().initial(f.pattern(ret,List.of(f.field("b")),Tail.STAR,star,ex));
   var s1=new Subscription(f.getKey(),new CallerRef(caller,p1,Layer.NORMAL,call,0),Layer.NORMAL,actual,false);
   var s2=new Subscription(f.getKey(),new CallerRef(caller,p2,Layer.NORMAL,call,0),Layer.NORMAL,actual,false);
   var pub=new Publication(initial,g);
   sm.subscribe(s1);sm.subscribe(s2);
   sm.onDelivery(f.getKey(),List.of(pub));sm.onDelivery(f.getKey(),List.of(pub));
   int rows=0;var edges=core.getEdges().edgesAt(call,(PremiseKey)null).iterator();while(edges.hasNext()){edges.next();rows++;}
   check(rows==2,"two exact origin supports");check(core.getEdgeDeltas()==2,"duplicate delivery makes no new semantic edge");
   // Publish first, then fresh third origin subscribes: real transformed replay now applies a result.
   storage.publish(List.of(pub));
   var p3=f.getManager().initial(f.pattern(ret,List.of(f.field("c")),Tail.STAR,star,ex));
   var s3=new Subscription(f.getKey(),new CallerRef(caller,p3,Layer.NORMAL,call,0),Layer.NORMAL,actual,false);sm.subscribe(s3);
