/** Safe observational callbacks. Every public callback catches its own failures. */
public final class DeliveryProbe {
 static final int OWNER_CAP=Integer.getInteger("opentaint.deliveryProbe.ownerCap",100000);
 static final int KEY_CAP=Integer.getInteger("opentaint.deliveryProbe.keyCap",2048);
 static final int SUPPORT_CAP=Integer.getInteger("opentaint.deliveryProbe.supportCap",32768);
 static final long LEAF_BUDGET=Long.getLong("opentaint.deliveryProbe.nodeBudget",262144L);
