 static final ConcurrentHashMap<String,String> transforms=new ConcurrentHashMap<>();
 static final ConcurrentHashMap<String,String> errorMessages=new ConcurrentHashMap<>();
 static final ThreadLocal<ArrayDeque<Scope>> SCOPES=ThreadLocal.withInitial(ArrayDeque::new);
 static final ClassValue<Field> PORT=new ClassValue<>(){protected Field computeValue(Class<?> c){try{Field f=c.getDeclaredField("port");f.setAccessible(true);return f;}catch(Exception e){throw new RuntimeException(e);}}};
 static final Object SAMPLE_LOCK=new Object();
 static final LinkedHashMap<Signature,Seen> SAMPLES=new LinkedHashMap<>();
 static long windowApps,flowEligible,zeroDirectEligible,otherInWindow,trackedApps,keyCapSkipped,supportCapSkipped,nodeBudgetSkipped,retainedLeaves,supports,crossOriginSupports,sameOriginRepeatedApps,sameOriginCrossScopeRepeatedApps,sameOriginCrossRegionRepeatedApps;
 static long windowFirstOrdinal,windowLastOrdinal;static Instant firstSampleAt,lastSampleAt;
 static final long[] pubKinds=new long[4];
 static final class Counts {
  final AtomicLong candidates=new AtomicLong(),matchInvocations=new AtomicLong(),matches=new AtomicLong(),applications=new AtomicLong(),zeroOnlyApps=new AtomicLong(),inputLeaves=new AtomicLong(),pubLeaves=new AtomicLong(),maxInputNodes=new AtomicLong(),maxPubLeaves=new AtomicLong();
  final AtomicLongArray premiseBases=new AtomicLongArray(3),conclusionBases=new AtomicLongArray(3),inputBases=new AtomicLongArray(3),conclusionTypes=new AtomicLongArray(3),inputTypes=new AtomicLongArray(3),pubNodesByKind=new AtomicLongArray(4),inputNodesByKind=new AtomicLongArray(4);
  final AtomicLongArray candidateKinds=new AtomicLongArray(4),matchKinds=new AtomicLongArray(4),appKinds=new AtomicLongArray(4),inputHistogram=new AtomicLongArray(32),pubHistogram=new AtomicLongArray(32);
 }
 record Owner(int run,String scope,Object caller,Object callee){}
 static final class Scope {
  final int run;final String kind;final ApMode mode;final Object callee;final long id;
  Owner previousOwner;Counts previousCounts;
  Scope(int r,String k,ApMode m,Object c){run=r;kind=k;mode=m;callee=c;id=scopeIds.incrementAndGet();}
 }
 /** Facts equality omits only protection; this wrapper restores exact protection membership to equality. */
 record FullFacts(Facts facts,Object protection){FullFacts(Facts f){this(f,f instanceof TaintTree t?t.getNonSubsumable():null);}}
 /** Original premise and event source are deliberately omitted, every return-context field is retained. */
 record Signature(int run,boolean run1,Direction direction,int fieldLimit,MarkMode marks,Object caller,Object callee,Object call,Object callerLayer,int stage,boolean zeroOnly,Object linkLayer,Object pubPremise,FullFacts pubConclusion,int member,FullFacts selectedActual){}
 static final class Origin {final String firstScope;final long firstRegion;Origin(Scope s){firstScope=s.kind;firstRegion=s.id;}}
 static final class Seen {final HashMap<Object,Origin> origins=new HashMap<>();long apps;final String firstScope;final int pubIdentity;Seen(Scope s,Object p,int pi){firstScope=s.kind;pubIdentity=pi;origins.put(p,new Origin(s));apps=1;}}
 public static void start(){
  try{Runtime.getRuntime().addShutdownHook(new Thread(DeliveryProbe::write,"delivery-probe-shutdown"));Thread t=new Thread(()->{while(true){try{Thread.sleep(60000);write();}catch(InterruptedException e){return;}catch(Throwable e){failure("snapshot-thread",e);}}},"delivery-probe-snapshot");t.setDaemon(true);t.start();write();}catch(Throwable t){failure("start",t);}
 }
 static void transformed(String n,String before,String after){transforms.put(n,before+":"+after);}
 static void failure(String at,Throwable t){errors.incrementAndGet();errorMessages.putIfAbsent(at,t.getClass().getName()+":"+String.valueOf(t.getMessage()));}
 static Scope scope(){return SCOPES.get().peekLast();}
 static void enter(Object manager,Object callee,String kind){try{SubscriptionPort p=(SubscriptionPort)PORT.get(manager.getClass()).get(manager);RunConfig c=p.getConfig();SCOPES.get().addLast(new Scope(c.getIndex(),kind,c.getMode(),callee));}catch(Throwable t){failure("enter:"+kind,t);SCOPES.get().addLast(new Scope(-1,kind,new ApMode(false,Direction.BACKWARD,1,MarkMode.FULL),callee));}}
 public static void enterDelivery(Object manager,Object callee){enter(manager,callee,"delivery");}
 public static void enterReplay(Object manager,Object storage){try{enter(manager,((SummaryStorage)storage).getMethod(),"replay");}catch(Throwable t){failure("enter:replay-storage",t);SCOPES.get().addLast(new Scope(-1,"replay",new ApMode(false,Direction.BACKWARD,1,MarkMode.FULL),storage));}}
 public static void exit(){try{ArrayDeque<Scope> s=SCOPES.get();if(s.isEmpty())failure("scope-underflow",new IllegalStateException("empty"));else s.removeLast();}catch(Throwable t){failure("exit",t);}}
 static Counts owner(Scope s,Subscription sub){
  Owner key=new Owner(s.run,s.kind,sub.getCaller(),sub.getCallee());if(key.equals(s.previousOwner))return s.previousCounts;
  Counts c=OWNERS.get(key);if(c==null){synchronized(OWNER_LOCK){c=OWNERS.get(key);if(c==null){if(OWNERS.size()>=OWNER_CAP){ownerOverflow.incrementAndGet();return null;}c=new Counts();OWNERS.put(key,c);}}}
