 static int bucket(long n){return n<=1?0:Math.min(31,64-Long.numberOfLeadingZeros(n-1));}
 static void candidateOne(Counts c,int k){if(c!=null){c.candidates.incrementAndGet();c.candidateKinds.incrementAndGet(k);}}
 static void matchOne(Counts c,int k,boolean yes){if(c!=null){c.matchInvocations.incrementAndGet();if(yes){c.matches.incrementAndGet();c.matchKinds.incrementAndGet(k);}}}
 static int baseKind(Object b){return b==org.opentaint.dataflow.ap.ifds.AccessPathBase.Zero.INSTANCE?0:b==org.opentaint.dataflow.ap.ifds.AccessPathBase.ClassStatic.INSTANCE?1:2;}
 static int factKind(Facts f){return f instanceof Reach?0:f instanceof FlowTree?1:2;}
 static void appliedOne(Counts c,int k,Subscription sub,Publication pub,int member){if(c!=null){c.applications.incrementAndGet();c.appKinds.incrementAndGet(k);if(sub.getZeroOnly())c.zeroOnlyApps.incrementAndGet();long a=leaves(sub.getAdded()),g=leaves(pub.getConclusion());c.inputLeaves.addAndGet(a);c.pubLeaves.addAndGet(g);c.maxInputNodes.accumulateAndGet(a,Math::max);c.maxPubLeaves.accumulateAndGet(g,Math::max);c.inputHistogram.incrementAndGet(bucket(a));c.pubHistogram.incrementAndGet(bucket(g));c.premiseBases.incrementAndGet(baseKind(pub.getPremise().member(member).getBase()));c.conclusionBases.incrementAndGet(baseKind(pub.getConclusion().getBase()));c.inputBases.incrementAndGet(baseKind(sub.getAdded().getBase()));c.conclusionTypes.incrementAndGet(factKind(pub.getConclusion()));c.inputTypes.incrementAndGet(factKind(sub.getAdded()));c.pubNodesByKind.addAndGet(k,g);c.inputNodesByKind.addAndGet(k,a);}}
 public static void candidate(Object sub,Object pub,int member){try{Scope s=scope();if(s==null)return;Subscription a=(Subscription)sub;int k=kind((Publication)pub);candidateOne(TOTAL,k);candidateOne(owner(s,a),k);}catch(Throwable t){failure("candidate",t);}}
 public static void matched(Object result,Object sub,Object pub,int member){try{Scope s=scope();if(s==null)return;Subscription a=(Subscription)sub;int k=kind((Publication)pub);matchOne(TOTAL,k,result!=null);matchOne(owner(s,a),k,result!=null);}catch(Throwable t){failure("matched",t);}}
 public static void applied(Object sub,Object pub,int member){try{Scope s=scope();if(s==null)return;Subscription a=(Subscription)sub;Publication p=(Publication)pub;int k=kind(p);appliedOne(TOTAL,k,a,p,member);appliedOne(owner(s,a),k,a,p,member);if(s.run==SAMPLE_RUN)sample(s,a,p,member,k);}catch(Throwable t){failure("applied",t);}}
 static void sample(Scope s,Subscription a,Publication p,int member,int k){
  long ordinal=appOrdinal.incrementAndGet();if(ordinal<=WINDOW_SKIP||ordinal>WINDOW_SKIP+WINDOW_LIMIT)return;
  synchronized(SAMPLE_LOCK){windowApps++;pubKinds[k]++;if(windowFirstOrdinal==0){windowFirstOrdinal=ordinal;firstSampleAt=Instant.now();}windowLastOrdinal=ordinal;lastSampleAt=Instant.now();
   boolean flow=p.getPremise() instanceof InitialAp && p.getPremise().member(member).getMark() instanceof MarkSlot.Star;
   boolean zero=p.getPremise().isZero()&&a.getZeroOnly();if(flow)flowEligible++;else if(zero)zeroDirectEligible++;else{otherInWindow++;return;}
   CallerRef r=a.getRef();Signature key=new Signature(s.run,s.mode.getRun1(),s.mode.getDirection(),s.mode.getFieldLimit(),s.mode.getMarkMode(),r.getCaller(),a.getCallee(),r.getCall(),r.getCallerLayer(),r.getStageOrdinal(),a.getZeroOnly(),a.getLinkLayer(),p.getPremise(),new FullFacts(p.getConclusion()),member,new FullFacts(a.getAdded()));
   Seen old=SAMPLES.get(key);if(old==null){if(SAMPLES.size()>=KEY_CAP){keyCapSkipped++;return;}long size=leaves(p.getConclusion())+leaves(a.getAdded());if(size>LEAF_BUDGET-retainedLeaves){nodeBudgetSkipped++;return;}if(supports>=SUPPORT_CAP){supportCapSkipped++;return;}SAMPLES.put(key,new Seen(s,r.getPremise(),System.identityHashCode(p)));supports++;retainedLeaves+=size;trackedApps++;return;}
