   old.apps++;trackedApps++;
  }
 }
 static String q(Object o){if(o==null)return "null";String s=String.valueOf(o);return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";}
