import java.lang.instrument.*;
import java.security.ProtectionDomain;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import org.objectweb.asm.*;
import org.objectweb.asm.commons.AdviceAdapter;

/** Observational hooks only. No target fields, arguments, results or production control decisions change. */
public final class DeliveryProbeAgent implements ClassFileTransformer {
 static final String E="org/opentaint/dataflow/bidi/engine/";
 static final String PAIR="(L"+E+"Subscription;L"+E+"Publication;I)V";
 static final Set<String> TARGETS=Set.of(E+"SubscriptionManager",E+"SubscriptionManagerKt",E+"RunMethodCallServices");
 static String sha(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception x){throw new RuntimeException(x);}}
 public static void premain(String args,Instrumentation i){
  DeliveryProbe.start();i.addTransformer(new DeliveryProbeAgent(),false);
 }
 public byte[] transform(ClassLoader l,String n,Class<?> c,ProtectionDomain pd,byte[] b){
  if(!TARGETS.contains(n))return null;
  try{byte[] out=instrument(n,b);DeliveryProbe.transformed(n,sha(b),sha(out));return out;}
  catch(Throwable t){DeliveryProbe.failure("transform:"+n,t);return null;}
 }
 static byte[] instrument(String n,byte[] b){
  ClassReader cr=new ClassReader(b);ClassWriter cw=new ClassWriter(cr,ClassWriter.COMPUTE_FRAMES);
  cr.accept(new ClassVisitor(Opcodes.ASM9,cw){
   public MethodVisitor visitMethod(int access,String name,String desc,String sig,String[] exceptions){
    MethodVisitor mv=super.visitMethod(access,name,desc,sig,exceptions);
    boolean scope=n.equals(E+"SubscriptionManager")&&(name.equals("onDelivery")&&desc.startsWith("(Lorg/opentaint/dataflow/ap/ifds/MethodEntryPoint;Ljava/util/List;")||name.equals("replay")&&desc.startsWith("(L"+E+"SummaryStorage;"));
    boolean candidate=n.equals(E+"SubscriptionManager")&&name.equals("applyMatch")&&desc.equals(PAIR);
    boolean applied=n.equals(E+"RunMethodCallServices")&&name.equals("applySummary")&&desc.equals(PAIR);
    boolean matches=n.equals(E+"SubscriptionManagerKt")&&name.equals("matches")&&desc.startsWith("(L"+E+"Subscription;L"+E+"Publication;I");
    if(!scope&&!candidate&&!applied&&!matches)return mv;
    return new AdviceAdapter(Opcodes.ASM9,mv,access,name,desc){
     Label begin=new Label(),end=new Label(),handler=new Label();
     protected void onMethodEnter(){
      if(scope){loadThis();loadArg(0);invokeStatic(Type.getType(DeliveryProbe.class),new org.objectweb.asm.commons.Method(name.equals("onDelivery")?"enterDelivery":"enterReplay","(Ljava/lang/Object;Ljava/lang/Object;)V"));mark(begin);}
      if(candidate||applied){loadArg(0);loadArg(1);loadArg(2);invokeStatic(Type.getType(DeliveryProbe.class),new org.objectweb.asm.commons.Method(candidate?"candidate":"applied","(Ljava/lang/Object;Ljava/lang/Object;I)V"));}
     }
     protected void onMethodExit(int op){
      if(matches&&op==ARETURN){dup();loadArg(0);loadArg(1);loadArg(2);invokeStatic(Type.getType(DeliveryProbe.class),new org.objectweb.asm.commons.Method("matched","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;I)V"));}
      if(scope&&op!=ATHROW)invokeStatic(Type.getType(DeliveryProbe.class),new org.objectweb.asm.commons.Method("exit","()V"));
     }
     public void visitMaxs(int stack,int locals){
      if(scope){mark(end);visitTryCatchBlock(begin,end,handler,"java/lang/Throwable");mark(handler);int x=newLocal(Type.getType(Throwable.class));storeLocal(x);invokeStatic(Type.getType(DeliveryProbe.class),new org.objectweb.asm.commons.Method("exit","()V"));loadLocal(x);throwException();}
      super.visitMaxs(stack,locals);
     }
    };
   }
  },ClassReader.EXPAND_FRAMES);return cw.toByteArray();
 }
}

