package observations.latedelivery;
import java.lang.instrument.*;
import java.security.*;
import java.util.*;
import org.objectweb.asm.*;
/** Adds one observational entry hook; retransformation preserves all existing observer/application instructions. */
public final class LateDeliveryAgent implements ClassFileTransformer {
 public static final String TARGET="org/opentaint/dataflow/bidi/engine/RunMethodCallServices";
 public static final String PAIR="(Lorg/opentaint/dataflow/bidi/engine/Subscription;Lorg/opentaint/dataflow/bidi/engine/Publication;I)V";
 public static void agentmain(String output,Instrumentation i)throws Exception{
  Class<?> target=null;for(Class<?> c:i.getAllLoadedClasses())if(c.getName().equals(TARGET.replace('/','.'))){target=c;break;}
  if(target==null)throw new IllegalStateException("Target not already loaded");
  if(!i.isModifiableClass(target))throw new IllegalStateException("Target not modifiable");
  LateDeliveryProbe.install(target.getClassLoader(),output);
  LateDeliveryAgent a=new LateDeliveryAgent();i.addTransformer(a,true);i.retransformClasses(target);LateDeliveryProbe.write(false);
 }
 public byte[] transform(ClassLoader l,String n,Class<?> c,ProtectionDomain pd,byte[] b){
  if(!TARGET.equals(n))return null;
  try{byte[] a=instrument(b);LateDeliveryProbe.binding(sha(b),sha(a));return a;}catch(Throwable t){LateDeliveryProbe.failure("transform",t);return null;}
 }
 public static String sha(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new RuntimeException(e);}}
 public static byte[] instrument(byte[] b){
  ClassReader cr=new ClassReader(b);ClassWriter cw=new ClassWriter(cr,ClassWriter.COMPUTE_MAXS);final int[] count={0};
  cr.accept(new ClassVisitor(Opcodes.ASM9,cw){public MethodVisitor visitMethod(int a,String n,String d,String s,String[] x){MethodVisitor mv=super.visitMethod(a,n,d,s,x);if(!n.equals("applySummary")||!d.equals(PAIR))return mv;count[0]++;return new MethodVisitor(Opcodes.ASM9,mv){public void visitCode(){super.visitCode();visitVarInsn(Opcodes.ALOAD,1);visitVarInsn(Opcodes.ALOAD,2);visitVarInsn(Opcodes.ILOAD,3);visitMethodInsn(Opcodes.INVOKESTATIC,"observations/latedelivery/LateDeliveryProbe","observe","(Ljava/lang/Object;Ljava/lang/Object;I)V",false);}};}},0);
  if(count[0]!=1)throw new IllegalStateException("Expected one applySummary, got "+count[0]);return cw.toByteArray();
 }
}

