import java.util.*;
import org.opentaint.dataflow.ap.ifds.AccessPathBase;
import org.opentaint.dataflow.bidi.ap.*;
import org.opentaint.dataflow.bidi.engine.*;
import org.opentaint.dataflow.bidi.fixtures.MethodAnalysisFixtures;
import org.opentaint.dataflow.bidi.interp.MicroEdgeKt;
import org.opentaint.dataflow.bidi.store.*;
/** Finite AP witness, not an observation of conductor's runtime facts.
 * Wrapper motif: tasks=w.getTasks(); result.a=tasks; result.b=tasks; return result.
 * Backward original supports ret.a.* and ret.b.* converge at the getter call.
 */
public class PremiseSupportControl {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] argv)throws Exception{
  try(MethodAnalysisFixtures f=new MethodAnalysisFixtures()){
   System.err.println("AP_CODE_SOURCE="+ApOps.class.getProtectionDomain().getCodeSource().getLocation());
   System.err.println("FIXTURE_CODE_SOURCE="+MethodAnalysisFixtures.class.getProtectionDomain().getCodeSource().getLocation());
   var empty=ExclusionSet.Empty.INSTANCE;var star=MarkSlot.Companion.getSTAR();var ret=AccessPathBase.Return.INSTANCE;
   var receiver=AccessPathBase.This.INSTANCE;var workflow=AccessPathBase.LocalVar.Companion.create(99);
   var mode=new ApMode(false,Direction.BACKWARD,3,MarkMode.FULL);
   InitialAp p1=f.getManager().initial(f.pattern(ret,List.of(f.field("a")),Tail.STAR,star,empty));
   InitialAp p2=f.getManager().initial(f.pattern(ret,List.of(f.field("b")),Tail.STAR,star,empty));
   InitialAp j=f.getManager().initial(f.pattern(ret,List.of(),Tail.STAR,star,empty));
   Facts a=f.fact(ret,List.of(),Tail.STAR,star,empty,Layer.NORMAL);
   Facts g=f.fact(receiver,List.of(f.field("tasks")),Tail.STAR,star,empty,Layer.NORMAL);
   var caller=f.getStore().key("wrapper",0);var call=f.inst(1);
   var r1=new CallerRef(caller,p1,Layer.NORMAL,call,0);var r2=new CallerRef(caller,p2,Layer.NORMAL,call,0);
   var s1=new Subscription(f.getKey(),r1,a.getLayer(),a,false);var s2=new Subscription(f.getKey(),r2,a.getLayer(),a,false);
   var directory=new CalleeSubscriptions(f.getOps(),null);
   check(directory.add(s1)!=null,"first origin admitted");check(directory.add(s2)!=null,"second origin admitted separately");
   var pub=new Publication(j,g);int candidateCount=0;var it=directory.candidates(pub,0,mode).iterator();while(it.hasNext()){it.next();candidateCount++;}
   check(candidateCount==2,"same publication sees both original supports");
   Facts[] images=new Facts[2];Facts[] bound=new Facts[2];Subscription[] ss={s1,s2};
   for(int i=0;i<2;i++){
    var actual=SubscriptionManagerKt.matches(ss[i],pub,0,f.getOps(),mode);check(actual!=null,"matching geometry");
    var out=new CollectingOut();f.getOps().applySummary(actual,j,g,mode,out,ss[i].getRef().getPremise());
    check(out.getResults().size()==1 && out.getMarkRequests().isEmpty(),"one pure image");images[i]=out.getResults().get(0);
    var back=new CollectingOut();f.getOps().applyEdge(images[i],ss[i].getRef().getPremise(),MicroEdgeKt.starEdge(receiver,List.of(),workflow,List.of()),false,mode,back,false,null,false);
    check(back.getResults().size()==1 && back.getMarkRequests().isEmpty(),"one bound image");bound[i]=back.getResults().get(0);
   }
   check(images[0].equals(images[1]),"different origins produce equal getter images");
   check(bound[0].equals(bound[1]),"different origins produce equal bind images");
   var point=new MethodEdgeStore(f.getManager(),caller,f.getLanguage(),3,false,false);
   check(point.add(call,p1,bound[0])!=null,"first support retained");
   check(point.add(call,p2,bound[1])!=null,"second support retained despite equal geometry");
   check(point.add(call,p1,bound[0])==null,"same support and image duplicate rejected");
   System.out.println("{\"state\":\"PASS\",\"scope\":\"finite production-AP witness, not campaign multiplicity\",\"distinctOriginalPremises\":2,\"acceptedInputGroups\":2,\"publicationCandidates\":2,\"equalGetterImages\":1,\"equalBindImages\":1,\"retainedPointSupports\":2,\"sameSupportDuplicateRejected\":true}");
   directory.clear();
  }
 }
}

