import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
public class StackPartition {
 static String name(RecordedFrame f) { RecordedMethod m=f.getMethod(); return m.getType().getName()+"."+m.getName(); }
 static boolean has(List<String> fs,String s){ for(String f:fs)if(f.startsWith(s))return true;return false; }
 static String phase(List<String> f){
  String p="org.opentaint.dataflow.bidi.";
  if(!has(f,p+"engine.SubscriptionManager.onDelivery"))return "outside-current-delivery";
  if(has(f,p+"engine.CalleeSubscriptions.candidates") || has(f,p+"engine.CalleeSubscriptions$candidates$") || has(f,p+"store.AddedFactAccumulator.snapshot"))return "delivery/candidate-snapshot";
  if(has(f,p+"engine.SubscriptionManagerKt.matches"))return "delivery/match";
  if(has(f,p+"engine.RunMethodCallServices.resumeCallees")){
   if(has(f,p+"engine.RunMethodAnalyzer.completeOutput") || has(f,p+"engine.RunMethodAnalyzer.admitOutput")){
    if(has(f,p+"ap.TrieOpsKt.subtract") || has(f,p+"ap.FlowGroup.subtractSubsumed") || has(f,p+"ap.TaintGroup.subtractSubsumed"))return "delivery/resume/output-admission/subtract";
    return "delivery/resume/output-admission/other";
   }
   if(has(f,p+"engine.RunMethodCallServices.cleanChain"))return "delivery/resume/clean-chain";
   if(has(f,p+"interp.FormApplier.stage"))return "delivery/resume/ordinary-stage";
   if(has(f,p+"engine.RunMethodAnalyzer.cut") || has(f,p+"ap.ApOps.limit"))return "delivery/resume/field-limit-own-work";
   return "delivery/resume/other";
  }
  if(has(f,p+"engine.RunMethodCallServices.summaryParts"))return "delivery/image/summary-parts";
  if(has(f,p+"ap.ApOps.applySummary"))return "delivery/image/geometry";
  return "delivery/other";
 }
 public static void main(String[] a)throws Exception{
  Instant from=Instant.parse(a[1]), to=Instant.parse(a[2]);
  Map<String,long[]> rows=new TreeMap<>();long execution=0,alloc=0,bytes=0,noStack=0;
  try(RecordingFile r=new RecordingFile(Path.of(a[0]))){while(r.hasMoreEvents()){
   RecordedEvent e=r.readEvent();Instant t=e.getStartTime();if(t.isBefore(from)||!t.isBefore(to))continue;
   String type=e.getEventType().getName();boolean x=type.equals("jdk.ExecutionSample"),b=type.equals("jdk.ObjectAllocationSample");if(!x&&!b)continue;
   long w=b?e.getLong("weight"):0;if(x)execution++;else{alloc++;bytes+=w;}
   RecordedStackTrace st=e.getStackTrace();if(st==null)noStack++;
   List<String> fs=new ArrayList<>();if(st!=null)for(RecordedFrame f:st.getFrames())fs.add(name(f));
   String phase=phase(fs);long[] c=rows.computeIfAbsent(phase,k->new long[3]);if(x)c[0]++;else{c[1]++;c[2]+=w;}
  }}
  System.out.printf("{\"window\":[\"%s\",\"%s\"],\"executionEvents\":%d,\"allocationEvents\":%d,\"allocationWeightBytes\":%d,\"noStackEvents\":%d,\"rows\":[",from,to,execution,alloc,bytes,noStack);
  boolean first=true;for(var e:rows.entrySet()){if(!first)System.out.print(",");first=false;long[] c=e.getValue();System.out.printf("{\"phase\":\"%s\",\"javaEvents\":%d,\"allocationEvents\":%d,\"allocationWeightBytes\":%d}",e.getKey(),c[0],c[1],c[2]);}System.out.println("]}");
 }
}

