68:     /** An explicit frame stack preserves stage order and keeps pending demotion local to this invocation. */
69:     private fun flow(ctx: CallContext, point: CallPoint, facts: List<PlanFact>, pendingDemotion: Boolean = false) {
70:         val core = active()
71:         check(!pendingDemotion || core.forward) { "Native must-record demotion is only forward" }
72:         val stack = ArrayDeque<Frame>()
73:         stack.addLast(Frame(point, facts, pendingDemotion))
74:         while (stack.isNotEmpty()) {
75:             core.ap.cancellation.checkpoint()
76:             val frame = stack.peekLast()
77:             if (!frame.entered) {
78:                 frame.entered = true
79:                 if (frame.point == ctx.plan.exit) {
80:                     for (fact in frame.facts) {
81:                         core.ap.cancellation.checkpoint()
82:                         val result = if (frame.pendingDemotion) toDemand(fact.facts) else fact.facts
83:                         core.cut(Cut.CALL, fact.premise, result) { premise, cut -> core.emitAfter(premise, ctx.node, cut) }
84:                     }
85:                     stack.removeLast()
86:                     continue
87:                 }
88:                 if (core.forward && frame.point == CallPoint.BOUND) {
89:                     for (fact in frame.facts) {
90:                         core.ap.cancellation.checkpoint()
91:                         val ordinal = ctx.plan.stages.indexOfFirst { it.from == frame.point }.coerceAtLeast(0)
92:                         frame.triggers += core.localServices.checkSinksAt(fact.premise, ctx.node, fact.facts, ctx.plan.sinks,
93:                             OperationInput(ResumeSite.CallStageInput(core.operation(ctx.node, ordinal)), fact.premise, fact.facts,
94:                                 CallResumeState(ctx.callerLayer, fact.identityCandidate, frame.pendingDemotion)))
95:                     }
96:                 }
97:                 if (core.config.run1 && frame.point == CallPoint.ADDED) observeUnresolved(ctx, frame.facts)
98:             }
99:             val stages = ctx.plan.stagesAt(frame.point)
100:             if (frame.next >= stages.size) { stack.removeLast(); continue }
101:             val stage = stages[frame.next++]
102:             val out = applyStage(ctx, stage, frame.facts, frame.triggers, frame.pendingDemotion)
103:             if (out.isNotEmpty()) stack.addLast(Frame(stage.to, out, frame.pendingDemotion))
104:         }

