18:     /** A queued replay keeps the established fresh delta, not an old cumulative root. */
19:     internal inner class Admission(val fresh: Subscription, private val handle: Int, val growth: Boolean = false) {
20:         val current: Subscription get() {
21:             if (handle < 0) return fresh
22:             val value = values.snapshot(handle)
23:             return Subscription(callees[handle], value.ref, value.group.layer, value.facts)
24:         }

29:     internal fun admit(sub: Subscription): Admission? {
30:         ops.manager.cancellation.checkpoint()
31:         check(!visitingQuestion) { "Question effects must be queued before changing N2 inputs" }
32:         if (sub.zeroOnly) {
33:             check(sub.ref.premise.isZero) { "A zero-only subscription needs a zero caller premise" }
34:             check(sub.added is Reach) { "A zero-only subscription needs REACH" }
35:             check(sub.linkLayer == sub.added.layer) { "The link layer must be the added fact's layer" }
36:             if (sub.ref in zeroParts) return null
37:             zeroParts[sub.ref] = sub
38:             statistics?.accepted(zeroOnly = true)
39:             return Admission(sub, -1)
40:         }
41:         val update = values.add(sub.ref, sub.linkLayer, sub.added) ?: return null
42:         if (update.newGroup) callees += sub.callee
43:         statistics?.accepted(newGroup = update.newGroup)
44:         ops.manager.forEachLeafPosition(update.delta) { base, path ->
45:             if (index.add(base, path, update.handle) && statistics != null) {
46:                 postings++
47:                 statistics.posted()
48:             }
49:         }
50:         // This immutable delta is retained only by the pending replay callback.
51:         return Admission(sub.copy(added = update.delta), update.handle, growth = !update.newGroup)

76:     fun candidates(pub: Publication, member: Int, mode: ApMode): Sequence<Subscription> = sequence {
77:         ops.manager.cancellation.checkpoint()
78:         val initial = pub.premise.member(member)
79:         val ids = LinkedHashSet<Int>()
80:         if (mode.run1) {
81:             ids += index.lookupExtensions(initial.base, initial.pathData)
82:             // Candidate ancestors are checked by the same full AP predicate
83:             // as replay. Exact ancestors and excluded components do not match.
84:             ids += index.lookupPrefixes(initial.base, initial.pathData)
85:         }
86:         else {
87:             ids += index.lookupPrefixes(initial.base, initial.pathData)
88:             if (initial.mark is MarkSlot.Star || initial.tail == Tail.STAR) ids += index.lookupExtensions(initial.base, initial.pathData)
89:         }
90:         // Capture every candidate value before callbacks can grow this directory.
91:         val snapshot = ArrayList<Subscription>(ids.size + if (pub.premise.isZero) zeroParts.size else 0)
92:         for (id in ids) {
93:             ops.manager.cancellation.checkpoint()
94:             val value = values.snapshot(id)
95:             snapshot += Subscription(callees[id], value.ref, value.group.layer, value.facts)
96:         }
97:         if (pub.premise.isZero) snapshot.addAll(zeroParts.values)
98:         for (sub in snapshot) {
99:             ops.manager.cancellation.checkpoint()
100:             yield(sub)
101:         }
102:     }

80:     /** T4: new leaves, or the whole merged value when a T2 annotation changes. */
81:     fun add(node: CommonInst, premise: PremiseKey, f: Facts): Facts? {
82:         m.cancellation.checkpoint()
83:         check(f.base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot enter method storage" }
84:         check((f is FlowTree) == premise.isFlow) { "K6: the conclusion kind follows the premise" }
85:         check(premise !is PremiseSet || f is TaintTree) { "A multi-premise edge must be TAINT" }
86:         val index = lm.getInstIndex(node)
87:         when (f) {
88:             is Reach -> {
89:                 val bits = reach.getOrPut(premise) { arrayOf(BitSet(size), BitSet(size)) }[f.layer.ordinal]
90:                 if (bits[index]) return null
91:                 bits.set(index)
92:                 return f
93:             }
94:             is FlowTree -> assert(f.root.boundedDepth <= fieldLimit) { "W3: a stored conclusion must be within the field limit" }
95:             is TaintTree -> assert(f.root.boundedDepth <= fieldLimit) { "W3: a stored conclusion must be within the field limit" }
96:         }
97:         packed?.let { statements ->
98:             val owner = statements[index] ?: FlowBackedSummaries(m, replaceCovered = false, interners = interners)
99:                 .also { statements[index] = it }
100:             return owner.add(premise, f)
101:         }
102:         val rows = groups.getOrPut(premise) {
103:             ScalarPremiseRows((premise as? InitialAp)?.takeUnless { it.isZero })
104:         }
105:         rows.full?.get(index)?.let { return it.add(f) }
106:         val kind = rows.initial?.let { m.identityKind(it, f) } ?: NOT_IDENTITY
107:         if (kind == NOT_IDENTITY) return promoteAndAdd(rows, index, f)
108:         val seen = rows.present(f.layer, index)
109:         val protected = kind == PROTECTED_IDENTITY
110:         if (seen && (!protected || rows.isProtected(f.layer, index))) return null
111:         rows.setPresent(f.layer, index)
112:         if (protected) rows.setProtected(f.layer, index)
113:         return f
114:     }

