139: /** One edge for each tail/mark kind, followed by a graft into every path having that kind. */
140: internal fun applySummaryPart(ops: ApOps, a: Facts, j: InitialAp, g: Facts, mode: ApMode, out: ApOut) {
141:     val m = ops.manager
142:     m.cancellation.checkpoint()
143:     check(a !is FlowTree || g is FlowTree) { "a FLOW fact satisfies only a `*` premise, whose summaries are FLOW" }
144:     for (kind in leafKinds(m, g, j)) {
145:         m.cancellation.checkpoint()
146:         val one = CollectingOut()
147:         ops.applyCompiledEdge(a, kind.edge, g.layer == Layer.DEMAND, -1, mode, one)
148:         // F78: applying an excluded abstract target preserves the interest on
149:         // the caller's original slot before publishing its excluded result.
150:         for (mark in one.markRequests) {
151:             m.cancellation.checkpoint()
152:             out.markRequest(mark)
153:         }
154:         for (r in one.results) {
155:             m.cancellation.checkpoint()
156:             out.result(kind.graft(r))
157:         }
158:     }

179: private class SummaryLeafKind(val edge: CompiledEdge, val graft: (Facts) -> Facts)
