181: private fun leafKinds(m: ApManager, g: Facts, j: InitialAp): List<SummaryLeafKind> {
182:     val jOwn = j.tail == Tail.ANY_TAINT
183:     val inputShared = if (jOwn) ExclusionSet.Empty else j.exclusion
184:     fun edge(tail: Tail, mark: MarkSlot, exclusion: ExclusionSet, toExclusion: ExclusionSet = ExclusionSet.Empty) =
185:         CompiledEdge(j.base, j.pathData, j.tail, j.mark, g.base, null, tail, mark,
186:             m.intern(exclusion),
187:             m.intern(if (jOwn) j.exclusion else ExclusionSet.Empty), m.intern(toExclusion))
188:     return when (g) {
189:         is Reach -> listOf(SummaryLeafKind(edge(Tail.EXACT, MarkSlot.Concrete(TaintMark.ZERO), ExclusionSet.Empty)) { it })
190:         is FlowTree -> listOf(SummaryLeafKind(edge(g.tail, MarkSlot.Star(g.markExclusion),
191:             if (g.tail == Tail.STAR || g.tail == Tail.EXACT) inputShared.union(g.exclusion) else inputShared,
192:             if (g.tail == Tail.ANY_TAINT) g.exclusion else ExclusionSet.Empty)) {
193:             graftSummary(m, g.root, { p -> p == FlowLeaf.LEAF }, it)
194:         })
195:         is TaintTree -> {
196:             val all = m.taintAlg.foldAll(g.root, m.cancellation)
197:             val anyTail = g.anyTail
198:             val kinds = ArrayList<SummaryLeafKind>()
199:             for (id in all.exact.ids) {
200:                 m.cancellation.checkpoint()
201:                 val mark = TaintMark(id)
202:                 kinds += SummaryLeafKind(edge(Tail.EXACT, MarkSlot.Concrete(mark), inputShared)) {
203:                     graftSummary(m, g.root, { p -> mark in p.exact }, it)
204:                 }
205:             }
206:             for (id in all.any.ids) {
207:                 m.cancellation.checkpoint()
208:                 val mark = TaintMark(id)
209:                 val shared = if (anyTail == Tail.STAR) inputShared.union(g.exclusion) else inputShared
210:                 val own = if (anyTail == Tail.ANY_TAINT) g.exclusion else ExclusionSet.Empty
211:                 kinds += SummaryLeafKind(edge(anyTail, MarkSlot.Concrete(mark), shared, own)) {
212:                     graftSummary(m, g.root, { p -> mark in p.any }, it)
213:                 }
214:             }
215:             kinds
216:         }
217:     }
218: }
