220: private fun <G : TrieLeaf> graftSummary(m: ApManager, g: TrieNode<G>, occurs: (G) -> Boolean, r: Facts): Facts =
221:     when (r) {
222:         is Reach -> r
223:         is FlowTree -> r.withRoot(checkNotNull(FlowAlgebra.graft(g, occurs, r.root, m.cancellation)))
224:         is TaintTree -> m.taintTree(r.base, r.layer,
225:             checkNotNull(m.taintAlg.graft(g, occurs, r.root, m.cancellation)), r.exclusion, r.anyTail,
226:             r.nonSubsumable?.let { m.taintAlg.graft(g, occurs, it, m.cancellation) })

