134: 
135:             val rest = subtractSubsumed(pending, list) ?: return null
136:             // Subtraction can remove the last must leaf. Its canonical key is then Empty E.
137:             val i = list.indexOfFirst {
138:                 m.cancellation.checkpoint()
139:                 it.anyTail == rest.anyTail && it.exclusion == rest.exclusion
140:             }
141:             if (i < 0) {
142:                 list += admittedTree(m, rest, interner.internIfRequired(rest.root), rest.nonSubsumable)
143:                 return rest
144:             }
145:             val stored = list[i]
146:             val (merged, delta) = alg.mergeAddDelta(stored.root, rest.root, m.cancellation)
147:             val protection = mergeProtection(stored.nonSubsumable, rest.nonSubsumable)
148:             val deltaRoot = mergeProtection(delta, rest.nonSubsumable) ?: return null
149:             list[i] = admittedTree(m, stored, interner.internIfRequired(merged), protection)
150:             return admittedTree(m, rest, deltaRoot, rest.nonSubsumable)
151:         }
152:     }
153: 
154:     private fun subtractSubsumed(t: TaintTree, others: List<TaintTree>): TaintTree? {
155:         val ordinary = subtract(t.root, t, others, protectedOnly = false)
156:         // Ordinary ANY coverage cannot consume a fresh protected EXACT dependency.
157:         val protection = t.nonSubsumable?.let { subtract(it, t, others, protectedOnly = true) }
158:         val root = mergeProtection(ordinary, protection) ?: return null
159:         if (root === t.root && protection === t.nonSubsumable) return t
160:         return admittedTree(m, t, root, protection)

59:     /** Conjunctive sources reverse into independent demand branches. Forward filters do not reverse. */
60:     fun reversed(): StatementSummary {
61:         val rev = ArrayList<MicroEdge>()
62:         for (e in edges) rev += MicroEdge(revOrFail(e.edge), e.forward, e.conjunctive, e.actionId)
63:         for (c in conjunctions) for (lit in c.literals) {
64:             val forward = PathEdge(lit.fact, c.target, ExclusionSet.Empty)
65:             rev += MicroEdge(revOrFail(forward), forward, conjunctive = true)
66:         }
67:         val back = StatementSummary(touched + targets, rev, emptyList(), emptyMap(), sources = sources.map { it.reversed() })
68:         return back.withIdentities(passOverBases(targets, touched))
69:     }

113:     fun build(): CallPlan {
114:         val sinks = sinks()
115:         val (callees, models, unresolved) = resolve()
116:         val zeroCanReturn = unresolved || callees.isNotEmpty() || models.any { it.second.zeroCanReturn }
117:         val back = bindBack()
118:         val stages = buildList {
119:             add(Edges(BEFORE, BOUND, BIND_IN, bindIn()))
120:             for (sink in sinks) if (sink.endFacts.isNotEmpty())
121:                 add(Edges(BOUND, REWRITTEN, END_FACTS, MicroEdgeBuilder().apply {
122:                     sink.endFacts.forEach { edge(it.edge) }
123:                 }.buildStage(), Guard.SinkTriggered(sink)))
124:             add(Edges(BOUND, REWRITTEN, SOURCES, sources(sinks, zeroCanReturn)))
125:             add(Actions(BOUND, ADDED, cleanSteps()))
126:             if (callees.isNotEmpty()) add(Callees(ADDED, RETURNED, callees))
127:             for ((target, model) in models) add(Predefined(ADDED, RETURNED, target, model, model.compile(manager)))
128:             if (unresolved) {
129:                 add(Edges(ADDED, RETURNED, UNRESOLVED, StatementSummary.identities(boundPositions())))
130:                 add(Edges(ADDED, RETURNED, UNRESOLVED, passRules()))
131:             }
132:             if (callee.isConstructor && models.none { it.first === callee })
133:                 add(Edges(ADDED, REWRITTEN, CONSTRUCTOR, StatementSummary.identities(boundPositions())))
134:             val rewriterSteps = rewriterSteps()
135:             add(if (forms.isRun1GroupView) Actions.run1GroupReturnRewriter(rewriterSteps, manager.marks)
136:                 else Actions.run1FullReturnRewriter(rewriterSteps, manager.marks))
137:             add(Edges(REWRITTEN, AFTER, BIND_BACK, back))
138:             aliases(back)?.let { add(Edges(REWRITTEN, AFTER, ALIASES, it, Guard.MemoryEffect)) }
139:         }
140:         val staged = stages.mapIndexed { ordinal, stage ->
141:             if (stage !is Edges) stage else stage.copy(summary = stage.summary.withStaticOperations(
142:                 stage.summary.staticOperations.map { operation ->
143:                     val id = operation.id.copy(stageOrdinal = ordinal)
144:                     when (operation) {
145:                         is StaticOperation.Read -> operation.copy(id = id)
146:                         is StaticOperation.Write -> operation.copy(id = id)
147:                         is StaticOperation.MarkInput -> operation.copy(id = id)
148:                     }
149:                 }))
150:         }
151:         return CallPlan(touched(), staged, sinks, entry = BEFORE, exit = AFTER, passReads = passReads,
152:             zeroCanReturn = zeroCanReturn)

179:     private fun bindIn(): StatementSummary = MicroEdgeBuilder().apply {
180:         edge(keepEdge(AccessPathBase.ClassStatic))
181:         edge(starEdge(AccessPathBase.Zero, emptyList(), AccessPathBase.Zero, emptyList()))
182:         o?.let {
183:             edge(starEdge(it, emptyList(), AccessPathBase.This, emptyList()))
184:             operandFilter(it, filter(callee.enclosingClass.toType()))
185:         }
186:         args.forEachIndexed { i, a ->
187:             if (a == null) return@forEachIndexed
188:             edge(starEdge(a, emptyList(), AccessPathBase.Argument(i), emptyList()))
189:             operandFilter(a, filter(call.args[i].type))
190:         }
191:     }.buildStage()
192: 
193:     /** Caller result filters act after bindings; no constant, local, exception or zero returns. */
194:     private fun bindBack(): StatementSummary = MicroEdgeBuilder().apply {
195:         edge(keepEdge(AccessPathBase.ClassStatic))
196:         if (o != null && o !is AccessPathBase.Constant) {
197:             edge(starEdge(AccessPathBase.This, emptyList(), o, emptyList()))
198:             resultFilter(o, filter((call as JIRInstanceCallExpr).instance.type))
199:         }
200:         args.forEachIndexed { i, a ->
201:             if (a == null || a is AccessPathBase.Constant) return@forEachIndexed
202:             edge(starEdge(AccessPathBase.Argument(i), emptyList(), a, emptyList()))
203:             resultFilter(a, filter(call.args[i].type))
204:         }
205:         if (r != null) {
206:             edge(starEdge(AccessPathBase.Return, emptyList(), r, emptyList()))
207:             resultFilter(r, filter(returnValue!!.type))
208:         }
209:     }.buildStage()

350:     /** Only local bind-back targets have persisted aliases. Helper-created edges own every full alias path. */
351:     private fun aliases(back: StatementSummary): StatementSummary? {
352:         val builder = MicroEdgeBuilder()
353:         for (e in back.edges) {
354:             val local = e.edge.to.base as? AccessPathBase.LocalVar ?: continue
355:             for (alias in persistedAliases(local, s)) {
356:                 val path = alias.accessors.map { it.apAccessor() }
357:                 if (enumAliasTargets.reject(alias.base, path)) continue
358:                 if (alias.base == local && alias.accessors.isEmpty()) continue
359:                 val transfer = starEdge(e.edge.from.base, emptyList(), alias.base,
360:                     path.map(manager.accessors::index))
361:                 builder.edge(transfer)
362:                 if (alias.base == AccessPathBase.ClassStatic)
363:                     builder.staticOperation(StaticOperation.Write(OperationId(formKey),
364:                         Pattern(transfer.to, ExclusionSet.Empty), transfer))
365:             }
366:         }
367:         return builder.buildStage().takeIf { it.edges.isNotEmpty() }

