98:     fun resolve(call: JIRCallExpr, location: JIRInst, context: JIRCallResolutionContext): List<MethodResolutionResult> {
99:         val method = call.method.method
100:         val methodIgnored = unitResolver.resolve(method) == UnknownUnit
101: 
102:         if (methodIgnored && alwaysIgnoreMethod(method)) {
103:             return listOf(MethodResolutionResult.MethodResolutionFailed)
104:         }
105: 
106:         if (call is JIRLambdaExpr) {
107:             // lambda expr is an allocation site. lambda calls resolved as virtual calls
108:             return emptyList()
109:         }
110: 
111:         if (call !is JIRVirtualCallExpr) {
112:             if (methodIgnored) {
113:                 return listOf(MethodResolutionResult.MethodResolutionFailed)
114:             }
115: 
116:             val ctxBuilder = MethodContextCreator(context, call, location, instanceTypeConstraints = null)
117:             return ctxBuilder.attachContext(method)
118:                 .map { MethodResolutionResult.ConcreteMethod(it) }
119:         }

201:     private fun resolveValueTypeConstraints(
202:         value: JIRValue,
203:         location: JIRInst,
204:         context: JIRCallResolutionContext,
205:     ): Set<TypeConstraintInfo>? {
206:         val epContext = context.methodEntryPoint.context
207:         val valueCls = (value.type as? JIRRefType)?.jIRClass ?: return null
208:         val defaultConstraint = TypeConstraintInfo(valueCls, exactType = false)
209: 
210:         if (value !is JIRLocalVar) {
211:             val base = MethodFlowFunctionUtils.accessPathBase(value)
212:             val contextType = base?.let { epContext.baseTypeConstraint(it) }
213:             val type = contextType?.let { selectTypeConstraint(defaultConstraint, it) } ?: defaultConstraint
214:             return setOf(type)
215:         }
216: 
217:         val aliasInfo = context.aliasAnalysis
218:             ?: return setOf(defaultConstraint)
219: 
220:         val aliases = aliasInfo.findAlias(AccessPathBase.LocalVar(value.index), location)
221:             ?: return setOf(defaultConstraint)
222: 
223:         val resultConstraints = hashSetOf<TypeConstraintInfo>()
224:         val contextMethodInstList = context.methodEntryPoint.method.let { it as JIRMethod }.instList
225:         for (aliasInfo in aliases) {
226:             when (aliasInfo) {
227:                 is AliasAllocInfo -> {
228:                     val allocInst = contextMethodInstList.getOrNull(aliasInfo.allocInst)
229:                         ?: continue
230: 
231:                     val allocExpr = (allocInst as? JIRAssignInst)?.rhv as? JIRNewExpr
232:                         ?: continue
233: 
234:                     val allocType = allocExpr.type as? JIRClassType ?: continue
235:                     resultConstraints += TypeConstraintInfo(allocType.jIRClass, exactType = true)
236:                 }
237: 
238:                 is AliasApInfo -> {
239:                     if (aliasInfo.accessors.isNotEmpty()) continue
240:                     if (aliasInfo.base is AccessPathBase.LocalVar) continue
241: 
242:                     val contextType = epContext.baseTypeConstraint(aliasInfo.base)
243:                     val type = contextType?.let { selectTypeConstraint(defaultConstraint, it) } ?: defaultConstraint
244:                     resultConstraints += type
245:                 }
246:             }
247:         }
248: 
249:         if (resultConstraints.isEmpty()) {
250:             return setOf(defaultConstraint)
251:         }
252: 
253:         return resultConstraints
254:     }
