256:     private fun MethodContext.baseTypeConstraint(base: AccessPathBase): TypeConstraintInfo? = when (this) {
257:         is EmptyMethodContext -> null
258:         is JIRInstanceTypeMethodContext -> typeConstraint.takeIf { base is AccessPathBase.This }
259:         is JIRArgumentTypeMethodContext -> typeConstraint.takeIf { base is AccessPathBase.Argument && base.idx == argIdx }
260:         is CombinedMethodContext -> first.baseTypeConstraint(base) ?: second.baseTypeConstraint(base)
261:         else -> error("Unexpected value for context: $this")
262:     }
263: 
264:     private fun selectTypeConstraint(left: TypeConstraintInfo, right: TypeConstraintInfo): TypeConstraintInfo {
265:         if (left.exactType) return left
266:         if (right.exactType) return right
267:         val cls = selectClass(left.type, right.type)
268:         return TypeConstraintInfo(cls, exactType = false)
269:     }
270: 
271:     private fun selectClass(base: JIRClassOrInterface, other: JIRClassOrInterface): JIRClassOrInterface {
272:         if (base == other) return base
273: 
274:         // other is more concrete
275:         if (other.isSubClassOf(base)) {
276:             return other
277:         }
278: 
279:         // todo
280:         return base

312:         private fun paramTypeConstraints(paramIdx: Int): Set<TypeConstraintInfo> {
313:             val arg = call.args.getOrNull(paramIdx) ?: return emptySet()
314:             return paramTypeConstraints.getOrPut(paramIdx) {
315:                 resolveValueTypeConstraints(arg, location, context).orEmpty()
316:             }
317:         }
