319:         fun attachContext(method: JIRMethod): List<MethodWithContext> {
320:             val contextTypeInfo = mutableListOf<ContextTypeInfo>()
321:             if (call is JIRInstanceCallExpr && !method.isConstructor) {
322:                 contextTypeInfo += ContextTypeInfo.Instance
323:             }
324: 
325:             method.parameters.forEach { param ->
326:                 if (!param.type.isClass) return@forEach
327:                 if (param.type.isObject()) return@forEach
328: 
329:                 contextTypeInfo += ContextTypeInfo.Param(param.index, param.type)
330:             }
331: 
332:             val methodContexts = createContexts(method, contextTypeInfo)
333:             return methodContexts.map { MethodWithContext(method, it) }
334:         }
335: 
336:         private fun createContexts(method: JIRMethod, typeInfos: List<ContextTypeInfo>): List<MethodContext> {
337:             if (typeInfos.isEmpty()) return listOf(EmptyMethodContext)
338: 
339:             val contexts = typeInfos.map { typeInfo ->
340:                 val typeConstraints = resolveTypes(typeInfo)
341: 
342:                 if (typeConstraints.isNullOrEmpty()) {
343:                     return@map listOf(EmptyMethodContext)
344:                 }
345: 
346:                 val type = typeInfo.typeCls(method)
347:                     ?: return@map listOf(EmptyMethodContext)
348: 
349:                 if (typeConstraints.any { type.isSubClassOf(it.type) }) {
350:                     return@map listOf(EmptyMethodContext)
351:                 }
352: 
353:                 mkMethodContext(typeInfo, typeConstraints)
354:             }
355: 
356:             val result = mutableListOf<MethodContext>()
357:             contexts.cartesianProductMapTo { contextArray ->
358:                 val context = contextArray.toSet().combine()
359:                 result += context
360:             }
361:             return result
362:         }
363: 
364:         private fun resolveTypes(typeInfo: ContextTypeInfo): Set<TypeConstraintInfo>? = when (typeInfo) {
365:             is ContextTypeInfo.Instance -> instanceTypes
366:             is ContextTypeInfo.Param -> paramTypeConstraints(typeInfo.idx)
367:         }
368: 
369:         private fun mkMethodContext(
370:             typeInfo: ContextTypeInfo,
371:             constraints: Set<TypeConstraintInfo>
372:         ): List<MethodContext> = when (typeInfo) {
373:             is ContextTypeInfo.Instance -> constraints.map { JIRInstanceTypeMethodContext(it) }
374:             is ContextTypeInfo.Param -> constraints.map { JIRArgumentTypeMethodContext(typeInfo.idx, it) }
375:         }

