34:     private fun MethodContext.locationClass(key: MethodKey, base: AccessPathBase): JIRClassOrInterface? = when (this) {
35:         is EmptyMethodContext -> if (base is AccessPathBase.This) (key.method as? JIRMethod)?.enclosingClass else null
36:         is JIRInstanceTypeMethodContext -> if (base is AccessPathBase.This) typeConstraint.type else null
37:         is JIRArgumentTypeMethodContext -> if (base is AccessPathBase.Argument && base.idx == argIdx) typeConstraint.type else null
38:         is CombinedMethodContext -> first.locationClass(key, base) ?: second.locationClass(key, base)
