42:     /** Zero is kept. A context-filtered initial base has its identity; source targets are gen only. */
43:     fun entryRules(interp: JIRInterpreter, entry: JIRMethodEntry, key: MethodKey,
44:                    aliasAnalysis: JIRLocalAliasAnalysis? = entry.aliasAnalysis,
45:                    potentialUnknownAliases: Boolean = false, view: RuleView = RuleView.FULL): RuleStatement {
46:         val method = key.method as JIRMethod
47:         val node = key.statement as JIRInst
48:         val rewriter = calleeRewriter(interp, aliasAnalysis, method, node, potentialUnknownAliases)
49:         val forms = interp.ruleForms(view)
50:         val builder = MicroEdgeBuilder().apply { keepZero() }
51:         val form = FormKey(interp.entries.formOwner, method, key, node)
52:         val bases = listOf<AccessPathBase>(AccessPathBase.This) + method.parameters.indices.map { AccessPathBase.Argument(it) }
53:         for (base in bases) {
54:             val cls = key.context.locationClass(key, base) ?: continue
55:             builder.keep(base)
56:             builder.operandFilter(base, interp.typeFilters.of(cls.toType()))
57:         }

