186:     @SuppressWarnings("unchecked")
187:     private Map<String, Object> replace(
188:             Map<String, Object> input, DocumentContext documentContext, String taskId) {
189:         Map<String, Object> result = new HashMap<>();
190:         for (Entry<String, Object> e : input.entrySet()) {
191:             Object newValue;
192:             Object value = e.getValue();
193:             if (value instanceof String) {
194:                 newValue = replaceVariables(value.toString(), documentContext, taskId);
195:             } else if (value instanceof Map) {
196:                 // recursive call
197:                 newValue = replace((Map<String, Object>) value, documentContext, taskId);
198:             } else if (value instanceof List) {
199:                 newValue = replaceList((List<?>) value, taskId, documentContext);
200:             } else {
201:                 newValue = value;
202:             }
203:             result.put(e.getKey(), newValue);
204:         }
205:         return result;
206:     }
