208:     @SuppressWarnings("unchecked")
209:     private Object replaceList(List<?> values, String taskId, DocumentContext io) {
210:         List<Object> replacedList = new LinkedList<>();
211:         for (Object listVal : values) {
212:             if (listVal instanceof String) {
213:                 Object replaced = replaceVariables(listVal.toString(), io, taskId);
214:                 replacedList.add(replaced);
215:             } else if (listVal instanceof Map) {
216:                 Object replaced = replace((Map<String, Object>) listVal, io, taskId);
217:                 replacedList.add(replaced);
218:             } else if (listVal instanceof List) {
219:                 Object replaced = replaceList((List<?>) listVal, taskId, io);
220:                 replacedList.add(replaced);
221:             } else {
222:                 replacedList.add(listVal);
223:             }
224:         }

233:     private Object replaceVariables(
234:             String paramString, DocumentContext documentContext, String taskId, int depth) {
235:         var matcher = PATTERN.matcher(paramString);
236:         var replacements = new LinkedList<Replacement>();
237:         while (matcher.find()) {
238:             var start = matcher.start();
239:             var end = matcher.end();
240:             var match = paramString.substring(start, end);
241:             String paramPath = match.substring(2, match.length() - 1);
242:             paramPath = replaceVariables(paramPath, documentContext, taskId, depth + 1).toString();
243:             // if the paramPath is blank, meaning no value in between ${ and }
244:             // like ${}, ${  } etc, set the value to empty string
245:             if (StringUtils.isBlank(paramPath)) {
246:                 replacements.add(new Replacement("", start, end));
247:                 continue;
248:             }
249:             if (EnvUtils.isEnvironmentVariable(paramPath)) {
250:                 String sysValue = EnvUtils.getSystemParametersValue(paramPath, taskId);
251:                 if (sysValue != null) {
252:                     replacements.add(new Replacement(sysValue, start, end));
253:                 }
254:             } else {
255:                 try {
256:                     replacements.add(new Replacement(documentContext.read(paramPath), start, end));
257:                 } catch (Exception e) {
258:                     LOGGER.warn(
259:                             "Error reading documentContext for paramPath: {}. Exception: {}",
260:                             paramPath,
261:                             e);
262:                     replacements.add(new Replacement(null, start, end));
263:                 }
264:             }
265:         }
266:         if (replacements.size() == 1
267:                 && replacements.getFirst().getStartIndex() == 0
268:                 && replacements.getFirst().getEndIndex() == paramString.length()
269:                 && depth == 0) {
270:             return replacements.get(0).getReplacement();
271:         }
272:         Collections.sort(replacements);
273:         var builder = new StringBuilder(paramString);
274:         for (int i = replacements.size() - 1; i >= 0; i--) {
275:             var replacement = replacements.get(i);
276:             builder.replace(
277:                     replacement.getStartIndex(),
278:                     replacement.getEndIndex(),
279:                     Objects.toString(replacement.getReplacement()));
280:         }
281:         return builder.toString().replaceAll("\\$\\$\\{", "\\${");

